                let value = match positional.get(1) {
                    Some(v) => v.clone(),
                    None => {
                        return Err(RuntimeError::Error(
                            "AnomalyDetector.add_datapoint() requires a value".to_string(),
                        ));
                    }
                };
                let mut new_fields = fields;
                for (k, v) in &mut new_fields {
                    if k == "datapoints" {
                        if let Value::Array(arr) = v {
                            arr.push(value.clone());
                        }
                        break;
                    }
                }
                return Ok(Value::Struct {
                    name: "AnomalyDetector".to_string(),
                    fields: new_fields,
                });
