                if datapoints.len() < 2 {
                    return Ok(Value::Float(0.0));
                }

                let threshold = match method.as_str() {
                    "zscore" => {
                        let n = datapoints.len() as f64;
                        let mean = datapoints.iter().sum::<f64>() / n;
                        let variance =
                            datapoints.iter().map(|x| (x - mean).powi(2)).sum::<f64>() / n;
                        let stddev = variance.sqrt();
                        mean + 2.0 * stddev
                    }
                    "iqr" => {
                        let mut sorted = datapoints.clone();
                        sorted
                            .sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
                        let n = sorted.len();
                        let q3 = sorted[3 * n / 4];
                        let q1 = sorted[n / 4];
                        let iqr = q3 - q1;
                        q3 + 1.5 * iqr
                    }
                    _ => 0.0,
                };
                return Ok(Value::Float(threshold));
