                        plugins.tracker_block = true;
                        // The shipped helper: one implementation shared with the native
                        // FFI. It blocks via Network.setBlockedURLs and registers the JS
                        // bundle with Page.addScriptToEvaluateOnNewDocument, so the block
                        // survives navigation. Errors are ignored, matching the former
                        // inline `let _ =` code.
                        let _ = rt.block_on(crate::browser::plugins::apply_plugins(
                            &plugins,
                            &page.client,
                            &page.session_id,
                        ));
                        Ok(Value::String("TrackerBlock enabled".to_string()))
