/// Phase 59: Route QuicTransfer.* calls to transfer_net module.
fn call_quic_transfer_sentinel(name: &str, positional: Vec<Value>) -> Result<Value, RuntimeError> {
    let dispatch_fn = match name {
        "QuicTransfer.listen" => "quic_listen",
        "QuicTransfer.connect" => "quic_connect",
        "QuicTransfer.send_file" => "quic_send_file",
        "QuicTransfer.receive" => "quic_receive_file",
        "QuicTransfer.send_bytes" => "quic_send_bytes",
        "QuicTransfer.status" => "quic_status",
        _ => {
            return Err(RuntimeError::Error(format!(
                "unknown QuicTransfer method: {name}"
            )));
        }
    };
    match crate::stdlib::transfer_net::dispatch(dispatch_fn, positional) {
        Some(Ok(v)) => Ok(v),
        Some(Err(e)) => Err(RuntimeError::Error(e)),
        None => Err(RuntimeError::Error(format!("{name}: dispatch failed"))),
    }
}

