            let username = positional.get(1).map(|v| v.as_string()).unwrap_or_default();
            let password = positional.get(2).map(|v| v.as_string()).unwrap_or_default();
            let session_key = (std::process::id() & 0xFF) as u8;
            let encrypted: Vec<u8> = password.bytes().map(|b| b ^ session_key).collect();
            let mut vault = CREDENTIAL_VAULT.lock().unwrap_or_else(|e| e.into_inner());
            vault.insert(cred_name.clone(), (username, encrypted));
            Ok(Value::Struct {
                name: "CredentialStoreResult".into(),
                fields: vec![
                    ("stored".into(), Value::Bool(true)),
                    ("name".into(), Value::String(cred_name)),
                    ("encrypted".into(), Value::Bool(true)),
                ],
            })
