    // ── File I/O Tests ─────────────────────────────────────────────────

    #[test]
    fn read_file_builtin() {
        // `read_file` returns the bare string on both engines (stdlib/fs.tl), so the contents are
        // used directly. The previous form matched on `Ok(content)`, which cannot match a success
        // value, so it surfaced as the runtime's non-exhaustive-match error rather than failing an
        // assertion about file reading.
        let (_, output) = run(r#"fn main() {
                let content = read_file("tests/fixtures/compile_test.tl")
                print(content.contains("main"))
                print(content.contains("fibonacci"))
            }"#);
        assert_eq!(output, vec!["true", "true"]);
    }

    #[test]
    fn read_file_missing_is_a_loud_error() {
        // stdlib/fs.tl: a read FAILURE is a loud runtime error, never an `Err` value and never an
        // empty string. run_result() hands back the interpreter's Result so the refusal is visible.
        let result = run_result(r#"fn main() {
                let content = read_file("__no_such_file_read_file_builtin__.txt")
                print(content)
            }"#);
        assert!(
            result.is_err(),
            "a missing file must be a loud error, not a printed value"
        );
    }

