    #[test]
    fn keypair_sign_verify_fail_closed() {
        // W2-04 / cycle-02/07 §D5 layer 2: `KeyPair.sign`/`KeyPair.verify`
        // were removed as a false interface (a KEM key cannot sign). Before
        // the guard they silently resolved to the generic HMAC / hash-compare
        // methods — a wrong "signature" and a constant `false` — so this test
        // pins the fail-closed replacement, not just "an error".
        for (label, src) in [
            (
                "sign",
                r#"fn main() {
                let kp = KeyPair.generate()
                let sig = kp.sign("hello")
                print(sig)
            }"#,
            ),
            (
                "verify",
                r#"fn main() {
                let kp = KeyPair.generate()
                let ok = kp.verify("hello", "00")
                print(ok)
            }"#,
            ),
        ] {
            let (tokens, lex_errors) = lexer::tokenize(src);
            assert!(lex_errors.is_empty(), "lex errors ({label}): {lex_errors:?}");
            let program = Parser::parse(tokens).unwrap();
            let mut interp = Interpreter::new();
            let result = interp.run(&program);
            let err_msg = match result {
                Ok(_) => panic!("KeyPair.{label} must fail closed, got a value"),
                Err(e) => format!("{e}"),
            };
            assert!(
                err_msg.contains(&format!("KeyPair.{label} was removed")),
                "error should name the removed surface ({label}): {err_msg}"
            );
            assert!(
                err_msg.contains("ML-DSA-87"),
                "error should point at the real signing surface ({label}): {err_msg}"
            );
        }
    }

