        let (_, output) = run(r#"fn main() {
                let words = ["hello", "world", "hello", "tallow", "world", "hello"]
                var counts = {}
                for word in words {
                    let current = counts.get(word, 0)
                    counts = counts.insert(word, current + 1)
                }
                print(counts["hello"])
                print(counts["world"])
                print(counts["tallow"])
            }"#);
