    #[test]
    fn complex_struct_with_methods() {
        let (_, output) = run(r#"struct Point { x: i64, y: i64 }
            impl Point {
                fn magnitude(self) -> i64 {
                    self.x * self.x + self.y * self.y
                }
                fn translate(self, dx: i64, dy: i64) -> Point {
                    Point { x: self.x + dx, y: self.y + dy }
                }
            }
            fn main() {
                let p = Point { x: 3, y: 4 }
                print(p.magnitude())
                let p2 = p.translate(1, 1)
                print(p2.x)
                print(p2.y)
            }"#);
        assert_eq!(output, vec!["25", "4", "5"]);
    }

    #[test]
    fn complex_enum_with_match() {
        let (_, output) = run(r#"enum Shape {
                Circle(radius: f64),
                Rectangle(width: f64, height: f64),
                Square(side: f64)
            }
            fn area(shape: Shape) -> f64 {
                match shape {
                    Circle(radius) -> 3.14159 * radius * radius
                    Rectangle(width, height) -> width * height
                    Square(side) -> side * side
                    _ -> 0.0
                }
            }
            fn main() {
                let c = Shape.Circle(radius: 5.0)
                let r = Shape.Rectangle(width: 3.0, height: 4.0)
                print(area(c))
                print(area(r))
            }"#);
        // `format_float_c` renders 6 significant digits (the house convention: "3.14159",
        // "78.5"), and 3.14159 * 25.0 is 78.53974999999999 in f64, so the printed form is
        // "78.5397". The old expectation carried 7 digits, which this printer never emits.
        assert_eq!(output, vec!["78.5397", "12"]);
    }

