        let (_, output) = run(r#"
            struct Price {
                value: f64,
                currency: String
            }
            fn parse_prices(values: []f64) -> []Price {
                var result = []
                for v in values {
                    result = result + [Price { value: v, currency: "USD" }]
                }
                result
            }
            fn main() {
                let values = [9.99, 19.99, 29.99]
                let prices = parse_prices(values)
                print(prices.len)
                for p in prices {
                    print(p.value)
                }
            }"#);
