    #[test]
    fn e2e_result_pipeline() {
        // Spec pattern: process results, filter_ok, collect
        let (_, output) = run(r#"
            fn process(x: i32) -> Result<i32> {
                if x % 2 == 0 { return Ok(x * 10) }
                Err("odd")
            }
            fn main() {
                let items = [1, 2, 3, 4, 5, 6]
                let results = items.map({ x -> process(x) })
                let goods = results.filter_ok()
                print(goods.len)
                print(goods.sum())
            }"#);
        assert_eq!(output, vec!["3", "120"]);
    }

    #[test]
    fn e2e_enum_state_machine() {
        let (_, output) = run(r#"
            enum State {
                Idle,
                Running(progress: i32),
                Done(result: String)
            }
            fn step(s: State) -> State {
                match s {
                    Idle -> State.Running(progress: 0)
                    Running(progress) -> {
                        if progress >= 100 {
                            State.Done(result: "complete")
                        } else {
                            State.Running(progress: progress + 50)
                        }
                    }
                    Done(result) -> s
                }
            }
            fn main() {
                var state = State.Idle
                state = step(state)
                state = step(state)
                state = step(state)
                state = step(state)
                match state {
                    Done(result) -> print(result)
                    _ -> print("not done")
                }
            }"#);
        assert_eq!(output, vec!["complete"]);
    }

