    #[test]
    fn log_multiple_levels() {
        let (_, output) = run(r#"fn main() {
                log.debug("detail")
                log.info("info msg")
                log.warn("warning")
                log.error("error occurred")
            }"#);
        assert_eq!(output.len(), 4);
        assert!(output[0].starts_with("[DEBUG] [") && output[0].contains("detail"));
        assert!(output[1].starts_with("[INFO] [") && output[1].contains("info msg"));
        assert!(output[2].starts_with("[WARN] [") && output[2].contains("warning"));
        assert!(output[3].starts_with("[ERROR] [") && output[3].contains("error occurred"));
    }

    #[test]
    fn log_privacy_auto_redacted() {
        // Belt-and-suspenders: if a Private value reaches log at runtime
        // (privacy_pass should catch this at compile time), it's auto-redacted
        let src = r#"
            type Email = private String
            fn main() {
                let e = "test@example.com" as Email
                log.info(e)
            }
        "#;
        let (tokens, lex_errors) = lexer::tokenize(src);
        assert!(lex_errors.is_empty());
        let program = Parser::parse(tokens).unwrap();
        let mut interp = Interpreter::new();
        let result = interp.run(&program);
        assert!(result.is_ok(), "auto-redact should not error");
        assert_eq!(interp.output.len(), 1);
        assert!(
            interp.output[0].contains("[REDACTED]"),
            "private should be redacted: {}",
            interp.output[0]
        );
    }

