    #[test]
    fn http_listen_creates_server() {
        // Port 0 = OS-assigned ephemeral port
        let (_, output) = run(r#"fn main() {
                let server = http.listen(0)
                let has_port = server.port > 0
                print(has_port)
                print(server.address)
                server.close()
            }"#);
        assert_eq!(output[0], "true");
        assert!(
            output[1].starts_with("127.0.0.1:"),
            "address should start with 127.0.0.1:"
        );
    }

    #[test]
    fn http_server_accept_respond() {
        use std::io::{Read as _, Write as _};
        use std::net::TcpStream;
        use std::thread;

        // Bind to port 0 (OS-assigned)
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let port = listener.local_addr().unwrap().port();
        drop(listener); // free the port

        // Start server in Tallow via stdlib
        let port_val = port;
        let handle = thread::spawn(move || {
            let code = format!(
                r#"fn main() {{
                    let server = http.listen({port_val})
                    let req = server.accept()
                    print(req.method)
                    print(req.path)
                    server.respond(req, 200, "hello from tallow")
                    server.close()
                }}"#
            );
            let (_, output) = run(&code);
            output
        });

        // Give server a moment to start
        thread::sleep(std::time::Duration::from_millis(100));

        // Connect as client
        let mut stream = TcpStream::connect(format!("127.0.0.1:{port}")).unwrap();
        stream
            .write_all(b"GET /test HTTP/1.1\r\nHost: localhost\r\n\r\n")
            .unwrap();
        stream.flush().unwrap();

        // Read response
        let mut response = String::new();
        stream.read_to_string(&mut response).unwrap();

        let output = handle.join().unwrap();
        assert_eq!(output[0], "GET");
        assert_eq!(output[1], "/test");
        assert!(response.contains("200 OK"));
        assert!(response.contains("hello from tallow"));
    }

