    #[test]
    fn e2e_compliant_scraper_pattern() {
        // Tests the core spec pattern: legal annotation + privacy + map
        let (_, output) = run(r#"
            @legal(
                basis: .public_data,
                purpose: "competitive price monitoring",
                personal_data: false,
                retain_for: 7.days,
                robots_txt: .respect,
                rate_limit: 2.per_second
            )
            fn scrape_prices(urls: []String) -> []String {
                let results = urls.map { url -> "price from {url}" }
                return results
            }
            fn main() {
                let urls = ["site-a.com", "site-b.com"]
                let results = scrape_prices(urls)
                print(results.len())
                print(results[0])
                print(results[1])
            }"#);
        assert_eq!(
            output,
            vec!["2", "price from site-a.com", "price from site-b.com"]
        );
    }

