    // ── E2E: Privacy-Safe User Processing (spec example 3) ──

    #[test]
    fn e2e_privacy_safe_user() {
        let (_, output) = run(r#"type Email = private String
            type Name = private String
            type Password = secret String

            struct User {
                id: i32,
                email: Email,
                name: Name
            }

            fn log_activity(user_id: i32, action: String) -> String {
                "[INFO] user {user_id} performed {action}"
            }

            fn main() {
                let email = "user@example.com" as Email
                let name = "Alice" as Name

                let user = User {
                    id: 42,
                    email: email,
                    name: name
                }

                // Can access non-private fields
                print(user.id)

                // Can log with ID (not private)
                let log_msg = log_activity(user.id, "login")
                print(log_msg)

                // Redact private types for safe output
                print(user.email.redact())
            }"#);
        assert_eq!(output[0], "42");
        assert!(output[1].contains("42"));
        assert!(output[1].contains("login"));
        assert!(output[2].contains("***"));
    }

    // ── E2E: Research Agent Pattern (spec example 4) ──

    #[test]
    fn e2e_research_agent_pattern() {
        let (_, output) = run(r#"@agent_task(
                id: task_id,
                timeout: 2.minutes,
                max_requests: 500,
                can_write: false,
                can_store: false,
                memory_limit: 256.mb
            )
            @legal(
                basis: .research,
                personal_data: false,
                purpose: "public market intelligence",
                retain_for: 90.days
            )
            async fn research_market(sector: String) -> Result<String> {
                let articles = ["article about {sector} #1", "article about {sector} #2"]
                let report = articles.join("; ")
                Ok(report.encrypt())
            }

            fn main() {
                let sectors = ["semiconductors", "AI"]
                let results = sectors.map { sector ->
                    research_market(sector).await
                }
                for r in results {
                    if let Ok(encrypted) = r {
                        let decrypted = encrypted.decrypt()
                        print(decrypted.contains("article"))
                    }
                }
            }"#);
        assert_eq!(output, vec!["true", "true"]);
    }

