    #[test]
    fn fastpath_fn_decl_is_shared_not_deep_cloned() {
        // Fast-path M3 (design 06 §3.1): a user-function lookup clones a
        // pointer (`Arc<FnDecl>`), not the AST body, so repeated lookups of the
        // same function return the same allocation (was: deep AST clone per call).
        let (tokens, lex_errors) = lexer::tokenize(
            r#"fn add(a: i64, b: i64) -> i64 { a + b }
               fn main() { print(add(1, 2)) }"#,
        );
        assert!(lex_errors.is_empty(), "lex errors: {lex_errors:?}");
        let program = Parser::parse(tokens).unwrap();
        let mut interp = Interpreter::new();
        interp.register(&program).unwrap();
        let first = interp.fn_decl_ptr("add").expect("add registered");
        let second = interp.fn_decl_ptr("add").expect("add registered");
        assert_eq!(first, second, "FnDecl body must be shared by pointer");
    }

