    // ── E2E: Full Pipeline Test ──

    #[test]
    fn e2e_full_data_pipeline() {
        let (_, output) = run(r#"
            struct DataRecord {
                source: String,
                value: i32,
                valid: bool
            }

            fn validate(record: DataRecord) -> Result<DataRecord> {
                if record.value < 0 { return Err("negative value") }
                if record.value > 1000 { return Err("value too large") }
                Ok(record)
            }

            fn transform(record: DataRecord) -> DataRecord {
                DataRecord {
                    ...record,
                    value: record.value * 2
                }
            }

            fn main() {
                let raw_data = [
                    DataRecord { source: "sensor-a", value: 42, valid: true },
                    DataRecord { source: "sensor-b", value: -5, valid: false },
                    DataRecord { source: "sensor-c", value: 100, valid: true }
                ]

                // Validate and transform pipeline
                let results = raw_data.map({ r -> validate(r) })
                let valid = results.filter_ok()
                let transformed = valid.map({ r -> transform(r) })

                print(raw_data.len())
                print(valid.len())
                print(transformed[0].value)
                print(transformed[1].value)
            }"#);
        assert_eq!(output, vec!["3", "2", "84", "200"]);
    }

    // ── Scope shadowing tests ──────────────────────────────────────────────

    #[test]
    fn variable_shadowing_in_block() {
        let (_, output) = run(r#"
            fn main() {
                let x = 10
                {
                    let x = 20
                    print(x)
                }
                print(x)
            }
        "#);
        assert_eq!(output, vec!["20", "10"]);
    }

    #[test]
    fn variable_shadowing_in_for_loop() {
        let (_, output) = run(r#"
            fn main() {
                let x = 100
                for x in [1, 2, 3] {
                    print(x)
                }
                print(x)
            }
        "#);
        // The loop binding is scoped to its iteration: an outer variable of the same name is
        // untouched once the loop ends. The previous expectation ("3") asserted the opposite and
        // contradicted both the per-iteration scope this arm pushes and the passing sibling test
        // variable_shadowing_in_match, which holds its outer binding at 42 through the match.
        // Making for-loops leak their binding instead would be a language-design change, not a
        // test correction, and would have to be decided deliberately.
        assert_eq!(output, vec!["1", "2", "3", "100"]);
    }

    #[test]
    fn variable_shadowing_in_match() {
        let (_, output) = run(r#"
            fn main() {
                let x = 42
                let result = x match {
                    42 -> "found"
                    _ -> "not found"
                }
                print(result)
                print(x)
            }
        "#);
        assert_eq!(output, vec!["found", "42"]);
    }

