    // ── Iterative algorithms ───────────────────────────────────────────────

    #[test]
    fn bubble_sort_algorithm() {
        let (_, output) = run(r#"
            fn main() {
                var arr = [5, 3, 8, 1, 2]
                var n = arr.len()
                var i = 0
                while i < n {
                    var j = 0
                    while j < n - 1 - i {
                        if arr[j] > arr[j + 1] {
                            let temp = arr[j]
                            arr[j] = arr[j + 1]
                            arr[j + 1] = temp
                        }
                        j += 1
                    }
                    i += 1
                }
                print(arr[0])
                print(arr[1])
                print(arr[2])
                print(arr[3])
                print(arr[4])
            }
        "#);
        assert_eq!(output, vec!["1", "2", "3", "5", "8"]);
    }

