    #[test]
    fn e2e_matrix_multiply_flat() {
        // 2x2 matrix multiply using flat arrays
        let (_, output) = run(r#"
            fn main() {
                // Matrix A = [[1, 2], [3, 4]] stored flat
                let a = [1, 2, 3, 4]
                // Matrix B = [[5, 6], [7, 8]] stored flat
                let b = [5, 6, 7, 8]
                // Result C[i][j] = sum(A[i][k] * B[k][j])
                let c00 = a[0]*b[0] + a[1]*b[2]
                let c01 = a[0]*b[1] + a[1]*b[3]
                let c10 = a[2]*b[0] + a[3]*b[2]
                let c11 = a[2]*b[1] + a[3]*b[3]
                print(c00)
                print(c01)
                print(c10)
                print(c11)
            }
        "#);
        assert_eq!(output, vec!["19", "22", "43", "50"]);
    }

