    #[test]
    fn e2e_recursive_tree_depth() {
        let (_, output) = run(r#"
            fn max(a: i32, b: i32) -> i32 {
                if a > b { a } else { b }
            }
            // Simulate binary tree as arrays: [value, left_depth, right_depth]
            fn tree_depth(depth: i32) -> i32 {
                if depth <= 0 { return 0 }
                1 + max(tree_depth(depth - 1), tree_depth(depth - 1))
            }
            fn main() {
                print(tree_depth(0))
                print(tree_depth(1))
                print(tree_depth(3))
                print(tree_depth(5))
            }
        "#);
        assert_eq!(output, vec!["0", "1", "3", "5"]);
    }

