    // ── Interpreter: complex algorithm ────────────────────────────────────

    #[test]
    fn selection_sort_algorithm() {
        let (_, output) = run(r#"
            fn sort(arr: []i32) -> []i32 {
                var a = arr
                let n = a.len()
                for i in 0..n {
                    var min_idx = i
                    for j in (i + 1)..n {
                        if a[j] < a[min_idx] {
                            min_idx = j
                        }
                    }
                    if min_idx != i {
                        let tmp = a[i]
                        a = a.set(i, a[min_idx])
                        a = a.set(min_idx, tmp)
                    }
                }
                a
            }
            fn main() {
                let arr = [5, 3, 8, 1, 9, 2]
                let sorted = sort(arr)
                for i in 0..sorted.len() {
                    print(sorted[i])
                }
            }
        "#);
        assert_eq!(output, vec!["1", "2", "3", "5", "8", "9"]);
    }

