    #[test]
    fn merge_two_sorted_arrays() {
        // Merge-sort merge step: combine two sorted arrays into one sorted array.
        let (_, output) = run(r#"
            fn merge_sorted(a: []i64, b: []i64) -> []i64 {
                var result = []
                var i = 0
                var j = 0
                while i < a.len() && j < b.len() {
                    if a[i] <= b[j] {
                        result = result + [a[i]]
                        i += 1
                    } else {
                        result = result + [b[j]]
                        j += 1
                    }
                }
                while i < a.len() {
                    result = result + [a[i]]
                    i += 1
                }
                while j < b.len() {
                    result = result + [b[j]]
                    j += 1
                }
                result
            }
            fn main() {
                let a = [1, 3, 5, 7]
                let b = [2, 4, 6, 8]
                let merged = merge_sorted(a, b)
                print(merged.len())
                print(merged[0])
                print(merged[4])
                print(merged[7])
            }
        "#);
        assert_eq!(output, vec!["8", "1", "5", "8"]);
    }

