    #[test]
    fn closure_callback_sort_comparator() {
        // Pass a comparator closure to bubble sort (avoids negative indexing).
        let (_, output) = run(r#"
            fn bubble_sort(arr: []i64, lt: fn(i64, i64) -> bool) -> []i64 {
                var a = arr
                var n = a.len()
                var i = 0
                while i < n {
                    var j = 0
                    while j < n - 1 - i {
                        if lt(a[j + 1], a[j]) {
                            let tmp = a[j]
                            a[j] = a[j + 1]
                            a[j + 1] = tmp
                        }
                        j += 1
                    }
                    i += 1
                }
                a
            }
            fn main() {
                let arr = [5, 2, 8, 1, 9, 3]
                let asc  = bubble_sort(arr, { a, b -> a < b })
                let desc = bubble_sort(arr, { a, b -> a > b })
                print(asc[0])
                print(asc[5])
                print(desc[0])
                print(desc[5])
            }
        "#);
        assert_eq!(output, vec!["1", "9", "9", "1"]);
    }

    #[test]
    fn error_propagation_chain_three_levels() {
        // Three functions each using ? — a failure at level 1 bubbles all the way up.
        let (_, output) = run(r#"
            fn parse_int_str(s: String) -> Result<i64> {
                if s == "" { return Err("empty string") }
                Ok(s.len())   // use len as a proxy for parsed value
            }
            fn double_parsed(s: String) -> Result<i64> {
                let n = parse_int_str(s)?
                Ok(n * 2)
            }
            fn pipeline(s: String) -> Result<String> {
                let v = double_parsed(s)?
                Ok("value={v}")
            }
            fn main() {
                let r1 = pipeline("hello")
                let r2 = pipeline("")
                match r1 {
                    Ok(v)  -> print(v)
                    Err(e) -> print("err:{e}")
                }
                match r2 {
                    Ok(v)  -> print(v)
                    Err(e) -> print("err:{e}")
                }
            }
        "#);
        assert_eq!(output, vec!["value=10", "err:empty string"]);
    }

