    #[test]
    fn string_pad_left_and_right_manual() {
        // Pad a string to a given width using loops — tests string concat + len.
        let (_, output) = run(r#"
            fn pad_left(s: String, width: i64, ch: String) -> String {
                var result = s
                while result.len() < width {
                    result = ch + result
                }
                result
            }
            fn pad_right(s: String, width: i64, ch: String) -> String {
                var result = s
                while result.len() < width {
                    result = result + ch
                }
                result
            }
            fn main() {
                print(pad_left("42", 5, "0"))
                print(pad_right("hi", 6, "."))
                print(pad_left("x", 4, "-"))
            }
        "#);
        assert_eq!(output, vec!["00042", "hi....", "---x"]);
    }

