    #[ignore] // Stack overflow on Windows — deep recursive Tallow function exceeds interpreter stack
    fn recursive_sum_nested_depth() {
        // Recursively sum a "triangle": sum(n) = n + sum(n-1), base 0.
        let (_, output) = run(r#"
            fn tri(n: i64) -> i64 {
                if n <= 0 { return 0 }
                n + tri(n - 1)
            }
            fn main() {
                print(tri(0))
                print(tri(1))
                print(tri(5))
                print(tri(10))
            }
        "#);
        assert_eq!(output, vec!["0", "1", "15", "55"]);
    }

