    #[test]
    fn gcd_and_lcm_combined() {
        // Compute GCD via Euclidean algorithm, then derive LCM = a*b/gcd.
        let (_, output) = run(r#"
            fn gcd(a: i64, b: i64) -> i64 {
                if b == 0 { return a }
                gcd(b, a % b)
            }
            fn lcm(a: i64, b: i64) -> i64 {
                a / gcd(a, b) * b
            }
            fn main() {
                print(gcd(48, 18))
                print(gcd(100, 75))
                print(lcm(4, 6))
                print(lcm(12, 18))
            }
        "#);
        assert_eq!(output, vec!["6", "25", "12", "36"]);
    }

    #[test]
    fn run_length_encoding() {
        // RLE encode: "aaabbc" → "3a2b1c", combining char scan with count.
        let (_, output) = run(r#"
            fn rle(s: String) -> String {
                if s.len() == 0 { return "" }
                let chars = s.chars()
                var result = ""
                var current = chars[0]
                var count = 1
                var i = 1
                while i < chars.len() {
                    if chars[i] == current {
                        count += 1
                    } else {
                        result = result + count.to_string() + current
                        current = chars[i]
                        count = 1
                    }
                    i += 1
                }
                result = result + count.to_string() + current
                result
            }
            fn main() {
                print(rle("aaabbc"))
                print(rle("abcd"))
                print(rle("zzzzz"))
            }
        "#);
        assert_eq!(output, vec!["3a2b1c", "1a1b1c1d", "5z"]);
    }

