    #[test]
    fn array_window_max() {
        // Sliding window of size 3: compute max in each window.
        let (_, output) = run(r#"
            fn window_max(arr: []i64, k: i64) -> []i64 {
                var result = []
                var i = 0
                while i <= arr.len() - k {
                    var mx = arr[i]
                    var j = 1
                    while j < k {
                        if arr[i + j] > mx { mx = arr[i + j] }
                        j += 1
                    }
                    result = result + [mx]
                    i += 1
                }
                result
            }
            fn main() {
                let arr = [1, 3, 2, 5, 4, 6]
                let wm = window_max(arr, 3)
                print(wm.len())
                print(wm[0])
                print(wm[1])
                print(wm[3])
            }
        "#);
        assert_eq!(output, vec!["4", "3", "5", "6"]);
    }

