    #[test]
    fn string_anagram_check() {
        // Check if two strings are anagrams by building frequency maps.
        let (_, output) = run(r#"
            fn char_freq(s: String) -> Map<String, i64> {
                var freq = {}
                for ch in s.chars() {
                    if freq.contains_key(ch) {
                        freq[ch] = freq[ch] + 1
                    } else {
                        freq[ch] = 1
                    }
                }
                freq
            }
            fn is_anagram(a: String, b: String) -> bool {
                if a.len() != b.len() { return false }
                let fa = char_freq(a)
                let fb = char_freq(b)
                for ch in a.chars() {
                    if !fb.contains_key(ch) { return false }
                    if fa[ch] != fb[ch]     { return false }
                }
                true
            }
            fn main() {
                print(is_anagram("listen", "silent"))
                print(is_anagram("hello", "world"))
                print(is_anagram("anagram", "nagaram"))
            }
        "#);
        assert_eq!(output, vec!["true", "false", "true"]);
    }

