    #[test]
    fn short_circuit_and_skips_rhs_on_false() {
        // If left side of && is false, right side should NOT execute.
        // We test this by having rhs do an array index that would panic.
        let (_, output) = run(r#"
            fn main() {
                let arr = [1, 2, 3]
                let idx = 100
                // Without short-circuit, arr[idx] would panic
                if false && arr[idx] > 0 {
                    print("bad")
                } else {
                    print("ok")
                }
            }
        "#);
        assert_eq!(output, vec!["ok"]);
    }

