    // ── nil comparison (nil == nil / x == nil) ────────────────────────

    #[test]
    fn eq_nil_terminates_and_matches_native_semantics() {
        // `x == nil` is the nil test: true only for nil; every present
        // value compares unequal (native: pointer-vs-null). Regression:
        // Struct/Map vs nil used to hit the catch-all type error
        // ("cannot apply Eq to Struct and nil").
        let (_, output) = run(r#"
            fn main() {
                let m = {"a": 1}
                print(m == nil)
                print(nil == m)
                print(m != nil)
                print(nil == nil)
                print(nil != nil)
                let s = "x"
                print(s == nil)
                print(nil == s)
            }
        "#);
        assert_eq!(
            output,
            vec!["false", "false", "true", "true", "false", "false", "false"]
        );
        // Direct struct coverage (no .tl literal constructs a bare Struct).
        let ti = Interpreter::new();
        let st = Value::Struct {
            name: "S".into(),
            fields: vec![],
        };
        assert!(matches!(
            ti.eval_binop(&BinOp::Eq, st.clone(), Value::Nil),
            Ok(Value::Bool(false))
        ));
        assert!(matches!(
            ti.eval_binop(&BinOp::Eq, Value::Nil, st.clone()),
            Ok(Value::Bool(false))
        ));
        assert!(matches!(
            ti.eval_binop(&BinOp::Neq, st, Value::Nil),
            Ok(Value::Bool(true))
        ));
    }

