    // ── KeyPair.from_seed deterministic generation ──────────────────

    #[test]
    fn keypair_from_seed() {
        let (_, output) = run(r#"
            fn main() {
                let kp1 = KeyPair.from_seed("my-seed-123")
                let kp2 = KeyPair.from_seed("my-seed-123")
                // Same seed → same public key
                print(kp1.public == kp2.public)
                print(kp1.algo)
            }
        "#);
        assert_eq!(output[0], "true");
        assert_eq!(output[1], "ml-kem-768");
    }

    #[test]
    fn keypair_from_seed_different_seeds() {
        let (_, output) = run(r#"
            fn main() {
                let kp1 = KeyPair.from_seed("seed-a")
                let kp2 = KeyPair.from_seed("seed-b")
                // Different seeds → different public keys
                print(kp1.public == kp2.public)
            }
        "#);
        assert_eq!(output, vec!["false"]);
    }

    #[test]
    fn keypair_from_pem() {
        let (_, output) = run(r#"
            fn main() {
                let result = KeyPair.from_pem("AAAA-base64-key-data")
                match result {
                    Ok(kp) -> print(kp.algo)
                    Err(e) -> print("error: {e}")
                }
            }
        "#);
        // `KeyPair.from_pem` detects EC / RSA / ED25519 / OPENSSH header substrings (and now
        // parses real ML-KEM DER); this input is not a PEM document at all, so "unknown" remains
        // the answer for it. The PQ round trip that could never return "ml-kem-768" is closed —
        // see `keypair_pem_round_trip_preserves_the_pq_algorithm` (stub #91).
        assert_eq!(output, vec!["unknown"]);
    }

    #[test]
    fn keypair_pem_round_trip_preserves_the_pq_algorithm() {
        // Stub #91: `to_pem` wrapped text in armour and `from_pem` read the algorithm off that
        // text, so a key this engine had just generated came back as `unknown`. The second
        // assertion is the stronger one — the document that comes back re-serializes to the
        // same PEM, which only holds if the encapsulation key survived the DER round trip. A
        // label would satisfy the first assertion on its own.
        let (_, output) = run(r#"
            fn main() {
                let kp = KeyPair.generate()
                let pem = kp.public.to_pem()
                let back = KeyPair.from_pem(pem)
                match back {
                    Ok(k) -> {
                        print(k.algo)
                        print(k.public.to_pem() == pem)
                    }
                    Err(e) -> print("error: {e}")
                }
            }
        "#);
        assert_eq!(output[0], "ml-kem-768");
        assert_eq!(output[1], "true", "the PEM document must survive the round trip intact");
    }

