    // ── Nested pattern matching with Box auto-unboxing ──────────────

    #[test]
    fn nested_enum_pattern_matching() {
        // Basic nested destructure: Add(Num(a), Num(b)) -> a + b
        let (_, output) = run(r#"
            enum Expr {
                Num(value: i64),
                Add(left: Box<Expr>, right: Box<Expr>)
            }
            fn eval(e: Expr) -> i64 {
                match e {
                    Num(value) -> value
                    Add(Num(a), Num(b)) -> a + b
                    Add(left, right) -> eval(left) + eval(right)
                }
            }
            fn main() {
                let e = Expr.Add(
                    left: Expr.Num(value: 3),
                    right: Expr.Num(value: 4)
                )
                print(eval(e))
            }
        "#);
        assert_eq!(output, vec!["7"]);
    }

    #[test]
    fn nested_pattern_mixed_bind_and_destructure() {
        // Mixed: one field destructured, one bound as variable
        let (_, output) = run(r#"
            enum Expr {
                Num(value: i64),
                Add(left: Box<Expr>, right: Box<Expr>)
            }
            fn eval(e: Expr) -> i64 {
                match e {
                    Num(value) -> value
                    Add(Num(a), right) -> a + eval(right)
                    Add(left, right) -> eval(left) + eval(right)
                }
            }
            fn main() {
                let e = Expr.Add(
                    left: Expr.Num(value: 10),
                    right: Expr.Add(
                        left: Expr.Num(value: 20),
                        right: Expr.Num(value: 30)
                    )
                )
                print(eval(e))
            }
        "#);
        assert_eq!(output, vec!["60"]);
    }

    #[test]
    fn nested_pattern_three_levels_deep() {
        // Three-level nesting: Add(Add(Num(a), Num(b)), Num(c))
        let (_, output) = run(r#"
            enum Expr {
                Num(value: i64),
                Add(left: Box<Expr>, right: Box<Expr>),
                Mul(left: Box<Expr>, right: Box<Expr>)
            }
            fn eval(e: Expr) -> i64 {
                match e {
                    Num(value) -> value
                    Add(left, right) -> eval(left) + eval(right)
                    Mul(left, right) -> eval(left) * eval(right)
                }
            }
            fn main() {
                // (2 + 3) * 4 = 20
                let e = Expr.Mul(
                    left: Expr.Add(
                        left: Expr.Num(value: 2),
                        right: Expr.Num(value: 3)
                    ),
                    right: Expr.Num(value: 4)
                )
                print(eval(e))
            }
        "#);
        assert_eq!(output, vec!["20"]);
    }

    #[test]
    fn nested_pattern_wildcard_inside_variant() {
        // Wildcard inside nested pattern
        let (_, output) = run(r#"
            enum Expr {
                Num(value: i64),
                Add(left: Box<Expr>, right: Box<Expr>)
            }
            fn has_add(e: Expr) -> bool {
                match e {
                    Add(_, _) -> true
                    _ -> false
                }
            }
            fn main() {
                let e1 = Expr.Num(value: 1)
                let e2 = Expr.Add(
                    left: Expr.Num(value: 1),
                    right: Expr.Num(value: 2)
                )
                print(has_add(e1))
                print(has_add(e2))
            }
        "#);
        assert_eq!(output, vec!["false", "true"]);
    }

    #[test]
    fn box_auto_unboxing_binds_inner_value() {
        // When binding a Box<Expr> field to a variable, the bound value
        // should be the inner Expr (auto-unboxed), usable directly
        let (_, output) = run(r#"
            enum Tree {
                Leaf(value: i64),
                Node(left: Box<Tree>, right: Box<Tree>)
            }
            fn sum_tree(t: Tree) -> i64 {
                match t {
                    Leaf(value) -> value
                    Node(left, right) -> sum_tree(left) + sum_tree(right)
                }
            }
            fn main() {
                let tree = Tree.Node(
                    left: Tree.Node(
                        left: Tree.Leaf(value: 1),
                        right: Tree.Leaf(value: 2)
                    ),
                    right: Tree.Leaf(value: 3)
                )
                print(sum_tree(tree))
            }
        "#);
        assert_eq!(output, vec!["6"]);
    }

    #[test]
    fn nested_pattern_ast_eval_full() {
        // AST evaluator — the target use case for self-hosting
        // Uses a shallow expression to avoid interpreter stack overflow on Windows
        let (_, output) = run(r#"
            enum Expr {
                Num(value: i64),
                Add(left: Box<Expr>, right: Box<Expr>),
                Neg(inner: Box<Expr>)
            }
            fn eval(e: Expr) -> i64 {
                match e {
                    Num(value) -> value
                    Add(left, right) -> eval(left) + eval(right)
                    Neg(inner) -> 0 - eval(inner)
                }
            }
            fn main() {
                // 2 + 3 = 5
                let e = Expr.Add(
                    left: Expr.Num(value: 2),
                    right: Expr.Num(value: 3)
                )
                print(eval(e))
            }
        "#);
        assert_eq!(output, vec!["5"]);
    }

