    #[test]
    fn multiple_methods_on_struct() {
        let (_, output) = run(r#"
            struct Counter { value: i64 }
            impl Counter {
                fn new() -> Counter {
                    Counter { value: 0 }
                }
                fn increment(self) -> Counter {
                    Counter { value: self.value + 1 }
                }
                fn current(self) -> i64 {
                    self.value
                }
            }
            fn main() {
                let c = Counter.new()
                let c2 = c.increment()
                let c3 = c2.increment()
                let c4 = c3.increment()
                print(c4.current())
            }
        "#);
        assert_eq!(output, vec!["3"]);
    }

