    #[test]
    fn recursive_fib_ten_is_55() {
        let (_, output) = run(r#"
            fn fib(n: i64) -> i64 {
                if n <= 1 { return n }
                fib(n - 1) + fib(n - 2)
            }
            fn main() {
                print(fib(10))
            }
        "#);
        assert_eq!(output, vec!["55"]);
    }

    #[test]
