    #[test]
    fn m02_pool_map_gate_is_sound() {
        // M-02: the parallel eligibility gate. `captures` is the closure's
        // whole visible scope (constants + locals, via `Env::all_bindings`);
        // the gate must pass when the body uses only constants/globals, and
        // must fail closed when it uses a captured local, a shadowing
        // binding, or an unmodelled construct.
        let span = Span::new(0, 0);
        let body_of = |name: &str| {
            vec![Stmt {
                kind: StmtKind::Expr {
                    expr: Expr::new(ExprKind::Ident(name.to_string()), span),
                },
                span,
            }]
        };
        let wordlist_val = Value::String("x".to_string());
        let consts_ser = vec![(
            "WORDLIST".to_string(),
            crate::agent_comm::value_to_channel_bytes(&wordlist_val).unwrap(),
        )];
        let caps = vec![
            ("WORDLIST".to_string(), wordlist_val.clone()),
            ("pool".to_string(), Value::Nil),
        ];
        // const use in body → worker-safe (constant is restored in workers)
        assert!(pool_map_body_is_worker_safe(
            &caps,
            &consts_ser,
            &body_of("WORDLIST")
        ));
        // local use in body → must fall back
        assert!(!pool_map_body_is_worker_safe(
            &caps,
            &consts_ser,
            &body_of("pool")
        ));
        // a shadowing binding (same name as a const, different value) → fall back
        let shadowed = vec![
            ("WORDLIST".to_string(), Value::Int(5)),
            ("pool".to_string(), Value::Nil),
        ];
        assert!(!pool_map_body_is_worker_safe(
            &shadowed,
            &consts_ser,
            &body_of("WORDLIST")
        ));
        // empty captures (top-level scope) → pass
        assert!(pool_map_body_is_worker_safe(
            &[],
            &consts_ser,
            &body_of("pool")
        ));
        // unmodelled construct (match) → fail closed
        let with_match = vec![Stmt {
            kind: StmtKind::Expr {
                expr: Expr::new(
                    ExprKind::Match {
                        subject: Box::new(Expr::new(ExprKind::Nil, span)),
                        arms: Vec::new(),
                    },
                    span,
                ),
            },
            span,
        }];
        assert!(!pool_map_body_is_worker_safe(
            &caps,
            &consts_ser,
            &with_match
        ));
    }

    #[test]
    fn m02_pool_map_parallel_constant_closure() {
        // M-02 end-to-end: with `TALLOW_POOL_WORKERS` set, a closure whose
        // body reads a top-level constant and calls a global helper that also
        // reads it must take the parallel path and still return the exact
        // sequential results, input order preserved. Before the M-02 gate fix
        // the parallel path was unreachable (`captures.is_empty()` never held
        // inside `main`); this pins the reachable path + constants carry.
        unsafe { std::env::set_var("TALLOW_POOL_WORKERS", "4") };
        let (_, output) = run(r#"
            const NAMES: []String = ["alpha", "beta", "gamma", "delta"]
            fn tag(i: i64) -> String { let n = NAMES[i % NAMES.len]; "{i}:{n}" }
            fn main() {
                let pool = IPPool.new(100)
                let indices = (0..4).collect()
                let r = pool.pool_map(indices) { i -> tag(i) }
                print(r.len)
                print(r[0])
                print(r[3])
            }
        "#);
        unsafe { std::env::remove_var("TALLOW_POOL_WORKERS") };
        assert_eq!(output, vec!["4", "0:alpha", "3:delta"]);
    }

