    #[test]
    fn browser_launch_returns_result() {
        // Browser.launch() should be callable from Tallow code
        // It returns Ok(<Browser>) or Err("...") depending on Chrome availability
        let (_, output) = run(r#"
            fn main() {
                let result = Browser.launch(true)
                // On CI without Chrome, this will be Err
                // On dev machine, this will be Ok(<Browser>)
                // Either way, it should be a valid Result value
                match result {
                    Ok(browser) -> {
                        print("got browser")
                        browser.close()
                    }
                    Err(e) -> {
                        print("no chrome")
                    }
                }
            }
        "#);
        // Accept either outcome — test verifies no panic/crash
        assert!(
            output == vec!["got browser"] || output == vec!["no chrome"],
            "unexpected output: {output:?}"
        );
    }

    #[test]
    fn browser_module_namespace() {
        // "Browser" should resolve to __module_Browser__ for dispatch
        let (_, output) = run(r#"
            fn main() {
                // Browser.launch dispatches through module namespace
                let result = Browser.launch(true)
                match result {
                    Ok(b) -> print("ok")
                    Err(e) -> print("err")
                }
            }
        "#);
        assert!(output == vec!["ok"] || output == vec!["err"]);
    }

    #[test]
    fn browser_runtime_singleton() {
        // Verify the runtime singleton can be created
        let rt = super::get_browser_runtime();
        // Should be able to block_on a simple future
        let result = rt.block_on(async { 42 });
        assert_eq!(result, 42);
        // Second call should return the same runtime (no panic)
        let rt2 = super::get_browser_runtime();
        let result2 = rt2.block_on(async { 99 });
        assert_eq!(result2, 99);
    }

