    #[test]
    fn agent_runtime_trust_decreases_on_failure() {
        // Agent A calls agent B which fails -> trust decreases
        let result = run_result(
            r#"@agent_task(
                id: failing_agent,
                timeout: 60.seconds,
                can_write: false,
                can_store: false
            )
            @legal(basis: .public_data, purpose: "helper")
            async fn failing_helper() -> Result<String> {
                bail "intentional failure"
            }

            @agent_task(
                id: caller_agent,
                timeout: 60.seconds,
                can_write: false,
                can_store: false
            )
            @legal(basis: .public_data, purpose: "caller")
            async fn caller() -> String {
                let result = failing_helper().await
                result match {
                    Ok(v) -> v
                    Err(e) -> "caught: {e}"
                }
            }

            fn main() {
                let r = caller().await
                print(r)
            }"#,
        );
        // The bail produces an Err value which is returned (not a runtime error)
        // The match catches it, so this should succeed
        match result {
            Ok(_) => {} // Success path: bail returns Err value, match catches it
            Err(e) => {
                // Also acceptable: if bail propagates as runtime error
                let msg = e.to_string();
                assert!(
                    msg.contains("intentional failure"),
                    "unexpected error: {msg}"
                );
            }
        }
    }

