    #[test]
    fn spawn_agent_crash_isolation_via_catch_unwind() {
        // NOTE (docs/PANIC-POLICY.md): this asserts containment that holds under the
        // TEST profile (unwind) ONLY. Shipped profiles set panic="abort", where the
        // process aborts before any catch can return — so this test does not describe
        // the artifact it appears to protect.
        // Test that catch_unwind path works at the Rust level
        // We verify the interpreter returns Err for a child error, parent continues
        let (_, output) = run(r#"@agent_task(
                id: crash_child,
                timeout: 60.seconds,
                can_write: false,
                can_store: false
            )
            @legal(basis: .public_data, purpose: "test")
            async fn crash_child() -> String {
                // This will error, not crash — but tests the error path
                panic("simulated crash")
            }

            @agent_task(
                id: parent_crash,
                timeout: 60.seconds,
                can_spawn: true,
                can_write: false,
                can_store: false
            )
            @legal(basis: .public_data, purpose: "test")
            async fn crash_parent() -> String {
                let result = spawn_agent("crash_child", "")
                match result {
                    Ok(v) -> "child ok: {v}"
                    Err(e) -> "isolated: {e}"
                }
            }
            fn main() {
                let r = crash_parent().await
                print(r)
            }"#);
        // Parent should have caught the error and continued
        assert!(
            output[0].starts_with("isolated:"),
            "Expected isolated error, got: {:?}",
            output
        );
    }

