    #[test]
    fn brain_semantic_related_traversal() {
        let (_, output) = run(r#"fn main() {
                let brain = Brain { working_capacity: 10, persistence: ":memory:" }
                brain.semantic.store("A", "connects_to", "B")
                brain.semantic.store("B", "connects_to", "C")
                brain.semantic.store("C", "connects_to", "D")
                let related = brain.semantic.related("A")
                print(related.len)
                // Should find at least A->B, B->C, C->D via graph traversal
                let has_b = false
                var found_cd = false
                for triple in related {
                    if triple.object == "D" {
                        found_cd = true
                    }
                }
                if found_cd { print("found D") }
            }"#);
        // related("A") with default depth 3 should traverse A->B->C->D
        let count: i128 = output[0].parse().unwrap();
        assert!(
            count >= 3,
            "expected at least 3 related triples, got {count}"
        );
        assert_eq!(output[1], "found D");
    }

    #[test]
    fn brain_procedural_versioning() {
        let (_, output) = run(r#"fn main() {
                let brain = Brain { working_capacity: 10, persistence: ":memory:" }
                let v1 = brain.procedural.store("parse_price", "return price * 1.0", "version 1")
                let v2 = brain.procedural.store("parse_price", "return price * 1.1", "version 2")
                print(v1)
                print(v2)
                let latest = brain.procedural.recall("parse_price")
                print(latest.version)
                print(latest.body)
                let old = brain.procedural.recall_version("parse_price", 1)
                print(old.body)
            }"#);
        assert_eq!(
            output,
            vec!["1", "2", "2", "return price * 1.1", "return price * 1.0"]
        );
    }

    #[test]
    fn brain_consolidation_transfers() {
        // Test consolidation via direct Rust API since store_with_kind method
        // needs kind specification which is easier to test at the Rust level
        let config = agent_memory::BrainConfig {
            working_capacity: 10,
            persistence_path: ":memory:".to_string(),
            ..agent_memory::BrainConfig::default()
        };
        let mut brain = agent_memory::Brain::new(config).unwrap();

        // Store items with specific kinds and high access_count
        brain.working.store_with_kind(
            "event1",
            "user clicked button",
            agent_memory::MemoryKind::Experience,
            0.8,
        );
        brain.working.store_with_kind(
            "sky",
            "blue|is|a_color",
            agent_memory::MemoryKind::Fact,
            0.9,
        );
        brain.working.store_with_kind(
            "parse_html",
            "fn parse() { ... }",
            agent_memory::MemoryKind::Procedure,
            0.8,
        );
        // This item has low importance and 0 access_count -- should NOT be consolidated
        brain.working.store("low_priority", "not important");

        // Bump access_count on the qualifying items
        brain.working.recall("event1");
        brain.working.recall("event1");
        brain.working.recall("sky");
        brain.working.recall("sky");
        brain.working.recall("parse_html");
        brain.working.recall("parse_html");

        assert_eq!(brain.working.len(), 4);

        let result = brain.consolidate().unwrap();
        assert_eq!(result.items_reviewed, 4);
        assert_eq!(result.to_episodic, 1); // experience
        assert_eq!(result.to_semantic, 1); // fact
        assert_eq!(result.to_procedural, 1); // procedure

        // Working memory should only have the low_priority item left
        assert_eq!(brain.working.len(), 1);
        assert!(brain.working.recall("low_priority").is_some());

        // Verify items landed in long-term stores
        assert_eq!(brain.episodic.count().unwrap(), 1);
        assert_eq!(brain.semantic.count().unwrap(), 1);
        assert_eq!(brain.procedural.count().unwrap(), 1);

        // Verify semantic triple was parsed from pipe-delimited format
        let triples = brain.semantic.query(Some("blue"), None, None).unwrap();
        assert_eq!(triples.len(), 1);
        assert_eq!(triples[0].predicate, "is");
        assert_eq!(triples[0].object, "a_color");
    }

    #[test]
    fn brain_persistence_across_instances() {
        let dir = std::env::temp_dir().join("tallow_brain_interp_test.db");
        let path = dir.to_string_lossy().to_string();
        let _ = std::fs::remove_file(&path);

        // Use escaped path for Tallow code
        let escaped_path = path.replace('\\', "\\\\");

        // Create brain, store data, drop it
        {
            let (_, output) = run(&format!(
                r#"fn main() {{
                    let brain = Brain {{ working_capacity: 10, persistence: "{escaped_path}" }}
                    brain.episodic.record("persistent event")
                    brain.semantic.store("Tallow", "is", "fast")
                    brain.procedural.store("skill1", "body1", "desc1")
                    print("stored")
                }}"#
            ));
            assert_eq!(output, vec!["stored"]);
        }

        // Create new brain with same path, verify data persists
        {
            let (_, output) = run(&format!(
                r#"fn main() {{
                    let brain = Brain {{ working_capacity: 10, persistence: "{escaped_path}" }}
                    let ep_count = brain.episodic.count()
                    let sem_count = brain.semantic.count()
                    let proc_count = brain.procedural.count()
                    print(ep_count)
                    print(sem_count)
                    print(proc_count)
                    let found = brain.episodic.search("persistent")
                    print(found.len)
                }}"#
            ));
            assert_eq!(output, vec!["1", "1", "1", "1"]);
        }

        let _ = std::fs::remove_file(&path);
    }

