    #[test]
    fn brain_full_lifecycle_with_reasoning() {
        let (_, output) = run(r#"fn main() {
                let brain = Brain { working_capacity: 10, persistence: ":memory:", reasoning: "rule_engine" }

                // Store working memory items
                brain.working.store("market", "bearish")
                brain.working.store("price", "dropping")

                // Record episodic entries
                brain.episodic.record("observed market downturn")

                // Store semantic triples
                brain.semantic.store("gold", "correlates_with", "uncertainty")

                // Add rules
                brain.add_rule("bear_market", ["bearish", "dropping"], "sell positions", 5)
                brain.add_rule("fallback", ["market"], "hold steady", 1)

                // Reason -- both rules should match (bearish + dropping present)
                let answer = brain.reason("what to do?")
                print(answer)

                // Verify reasoning chain
                let chain_len = brain.reasoning_chain_len()
                print(chain_len)

                // Verify chain entry has correct fields
                let chain = brain.reasoning_chain()
                let step = chain[0]
                print(step.backend)

                // Verify memory state
                let wc = brain.working_count()
                print(wc)

                let ec = brain.episodic_count()
                print(ec)

                let sc = brain.semantic_count()
                print(sc)
            }"#);
        // First output: joined actions (bear_market higher priority, then fallback)
        assert!(output[0].contains("sell positions"), "got: {}", output[0]);
        assert!(output[0].contains("hold steady"), "got: {}", output[0]);
        // Chain length = 1
        assert_eq!(output[1], "1");
        // Backend name
        assert_eq!(output[2], "rule_engine");
        // Working memory count = 2
        assert_eq!(output[3], "2");
        // Episodic count = 1
        assert_eq!(output[4], "1");
        // Semantic count = 1
        assert_eq!(output[5], "1");
    }

