    #[test]
    fn concurrency_spawn_await_collects_result() {
        let source = include_str!("../tests/fixtures/concurrency_spawn_await.tl");
        let (_, output) = run(source);
        // spawn returns a handle; spawn_await(handle) collects the goroutine's
        // value (worker(5) -> 50). The value crosses as bytes and round-trips.
        assert!(
            output.iter().any(|l| l.contains("50")),
            "expected the awaited value 50 in output, got: {:?}",
            output
        );
        assert!(output.contains(&"m:start".to_string()));
        assert!(output.contains(&"m:end".to_string()));
    }

