    #[test]
    fn spawn_agent_async_binds_declared_defaults() {
        // Only parameter names crossed the thread boundary, so an omitted
        // argument used to bind Nil and the child computed 10 instead of 17.
        let source = r#"
@agent_task(id: "d1", timeout: 60.seconds, max_requests: 100, can_write: false, can_store: false, can_spawn: false)
fn task(x: i32, bump: i32 = 7) -> i32 { x + bump }

fn main() {
    let h = spawn_agent_async("task", 10)
    print(spawn_await(h))
}
"#;
        let (_, output) = run(source);
        assert!(
            output.iter().any(|line| line.contains("17")),
            "declared default bump=7 must be bound before the args cross the thread boundary, got: {output:?}"
        );
    }

    // ── F1: cooperative scheduler (increment 1) ─────────────────────────
    //
    // `run_coop` runs a program with the interpreter-side task scheduler
    // enabled; legacy `run` is unchanged and still uses eager threads.

    fn run_coop(source: &str) -> (Value, Vec<String>) {
        let (tokens, lex_errors) = lexer::tokenize(source);
        assert!(lex_errors.is_empty(), "lex errors: {lex_errors:?}");
        let program = Parser::parse(tokens).unwrap();
        let mut interp = Interpreter::new();
        interp.set_coop_scheduler(true);
        let result = interp.run(&program).unwrap();
        (result, interp.output)
    }

    /// Like `run_coop` but returns Result — for the deadlock fail-loud path.
    fn run_coop_result(source: &str) -> Result<Value, RuntimeError> {
        let (tokens, lex_errors) = lexer::tokenize(source);
        assert!(lex_errors.is_empty(), "lex errors: {lex_errors:?}");
        let program = Parser::parse(tokens).unwrap();
        let mut interp = Interpreter::new();
        interp.set_coop_scheduler(true);
        interp.run(&program)
    }

    #[test]
    fn coop_sched_defers_start_and_spawn_await_returns_value() {
        let (_, output) = run_coop(
            r#"
            fn worker(x: i32) -> i32 { print("worker:run") x * 10 }
            fn main() {
                let h = spawn worker(5)
                print("main:after-spawn")
                let v = spawn_await(h)
                print(v)
            }
            "#,
        );
        // Deferred start: no part of the task body runs before the await point
        // (legacy thread mode starts it eagerly, so this order is not guaranteed
        // there); spawn_await then yields the task's value inside the Result Ok
        // wrapper — the cross-mode `spawn_await(handle) -> Result<Value>`
        // contract legacy threads and native codegen both follow (pinned: Ok(50);
        // .unwrap() yields 50, see the fixture trace assertions).
        assert_eq!(output, vec!["main:after-spawn", "worker:run", "Ok(50)"]);
    }

    #[test]
    fn coop_sched_await_suspends_and_schedules_ready_tasks_fifo() {
        let (_, output) = run_coop(include_str!(
            "../tests/fixtures/sched_coop_await_order.tl"
        ));
        // Deterministic FIFO trace. `other:run` between `mid:waiting` and
        // `mid:done` is the suspension proof: while `mid` awaited `leaf`, the
        // driver ran another ready task instead of `mid` blocking the thread.
        assert_eq!(
            output,
            vec![
                "main:await-mid",
                "mid:start",
                "mid:waiting",
                "other:run",
                "leaf:run",
                "mid:done",
                "main:mid-done",
                "42",
                "1",
            ]
        );
    }

    #[test]
    fn coop_sched_deadlock_fails_loud() {
        // Handle 0 is the first spawn id in a fresh interpreter, so this task
        // awaits its own handle and can never complete: the scheduler must
        // report a deadlock naming the handle instead of hanging.
        let err = run_coop_result(
            r#"
            fn selfwait() -> i32 {
                let r = spawn_await(0)
                r
            }
            fn main() {
                let h = spawn selfwait()
                print("main:spawned")
                let v = spawn_await(h)
                print("main:done")
                v
            }
            "#,
        )
        .expect_err("a self-await must fail loud, not hang");
        let msg = err.to_string();
        assert!(msg.contains("deadlock"), "expected a deadlock error, got: {msg}");
        assert!(
            msg.contains("handle 0"),
            "deadlock must name the awaited handle, got: {msg}"
        );
    }

    #[test]
    fn coop_sched_drains_unawaited_tasks_at_exit() {
        let (_, output) = run_coop(
            r#"
            fn bg() -> i32 { print("bg:ran") 1 }
            fn main() {
                let h = spawn bg()
                print("main:end")
                h
            }
            "#,
        );
        // Join-at-exit: a spawned task that is never awaited still runs before
        // the program returns (same contract as the legacy thread handles).
        assert_eq!(output, vec!["main:end", "bg:ran"]);
    }

    #[test]
    fn coop_sched_await_keyword_joins_task_handle() {
        let src = include_str!("../tests/fixtures/sched_await_value.tl");
        // Coop mode: `.await` on a task handle is a real join and yields the value.
        let (_, coop_out) = run_coop(src);
        assert_eq!(coop_out, vec!["50"]);
        // Legacy mode: `.await` is the documented no-op pass-through — it returns
        // the handle itself (0 = first spawn id), not the task's value. This pin
        // documents the behavior F1 replaces (legacy mode stays untouched).
        let (_, legacy_out) = run(src);
        assert_eq!(legacy_out, vec!["0"]);
    }

