    #[test]
    fn test_agent_snapshot_and_rollback() {
        let (_, output) = run(r#"
            fn main() {
                let brain = Brain { working_capacity: 10, persistence: ":memory:" }
                brain.episodic.record("event1")
                brain.semantic.store("A", "is", "B")
                brain.procedural.store("skill1", "body1", "desc1")

                let snap = brain.snapshot("before_change")
                print(snap)

                brain.episodic.record("event2")
                brain.semantic.store("C", "is", "D")
                print(brain.episodic_count())
                print(brain.semantic_count())

                brain.rollback("before_change")
                print(brain.episodic_count())
                print(brain.semantic_count())
            }
        "#);
        assert_eq!(output, vec!["before_change", "2", "2", "1", "1"]);
    }

