    // ── Agent Quarantine Integration Tests ────────────────────────────────

    #[test]
    fn test_agent_quarantine_episodic() {
        let (_, output) = run(r#"
            fn main() {
                let brain = Brain { working_capacity: 10, persistence: ":memory:" }
                brain.episodic.record("good event")
                brain.episodic.record("bad event")

                let all = brain.episodic.search("event")
                print(all.len)

                // Find the bad event's ID
                var bad_id = 0
                for entry in all {
                    if entry.content == "bad event" {
                        bad_id = entry.id
                    }
                }

                brain.episodic.quarantine(bad_id)
                let visible = brain.episodic.search("event")
                print(visible.len)

                let qlist = brain.episodic.quarantined()
                print(qlist.len)
                print(qlist[0].content)
            }
        "#);
        assert_eq!(output, vec!["2", "1", "1", "bad event"]);
    }

    #[test]
    fn test_agent_quarantine_restore() {
        let (_, output) = run(r#"
            fn main() {
                let brain = Brain { working_capacity: 10, persistence: ":memory:" }
                brain.episodic.record("test item")
                let entries = brain.episodic.search("test")
                let id = entries[0].id

                brain.episodic.quarantine(id)
                print(brain.episodic.count())

                brain.episodic.restore(id)
                print(brain.episodic.count())
            }
        "#);
        assert_eq!(output, vec!["0", "1"]);
    }

