    #[test]
    fn test_agent_learn_function_basic() {
        // Use \{ and \} to escape braces in Tallow strings (avoids string interpolation)
        let (_, output) = run(r#"
            fn main() {
                let src = "fn double(x: i32) -> i32 \{ x * 2 \}"
                let result = learn_function(src)
                print(result)
                let val = double(21)
                print(val)
            }
        "#);
        // Result is Ok("double"), second is 42
        assert!(
            output[0].contains("double"),
            "expected Ok(double), got: {}",
            output[0]
        );
        assert_eq!(output[1], "42");
    }

