    #[test]
    fn test_crash_recovery_restores_steps() {
        // Test crash recovery by creating a checkpoint store with pre-existing data
        // and verifying the agent picks it up
        use crate::agent_observability::CheckpointStore;
        use crate::agent_runtime::{AgentRuntime, ResourceBudget};
        use rusqlite::Connection;
        use std::cell::RefCell;
        use std::rc::Rc;

        // Create an in-memory SQLite, save a checkpoint, then run an agent
        let conn = Connection::open_in_memory().unwrap();
        let shared = std::sync::Arc::new(std::sync::Mutex::new(conn));
        let cp_store = CheckpointStore::new(std::sync::Arc::clone(&shared)).unwrap();

        // Create a runtime and save a checkpoint manually
        let mut rt = AgentRuntime::new(
            "recovery_test".to_string(),
            None,
            None,
            ResourceBudget::new(Some(100), None, Some(std::time::Duration::from_secs(60))),
        );
        rt.steps_executed = 42;
        rt.emotional_state.confidence = 0.95;
        rt.emotional_state.urgency = 0.1;
        rt.emotional_state.uncertainty = 0.05;
        rt.goals_attempted = 10;
        rt.goals_completed = 8;
        cp_store
            .save_checkpoint("recovery_test", &rt, "[]", 100)
            .unwrap();

        // Verify we can load it back
        let loaded = cp_store
            .load_latest_checkpoint("recovery_test")
            .unwrap()
            .unwrap();
        assert_eq!(loaded.steps_executed, 42);
        assert!((loaded.confidence - 0.95).abs() < f64::EPSILON);
        assert_eq!(loaded.goals_attempted, 10);
        assert_eq!(loaded.goals_completed, 8);
    }

    #[test]
    fn test_crash_recovery_restores_emotional_state() {
        // Round-trip emotional state through checkpoint
        use crate::agent_observability::CheckpointStore;
        use crate::agent_runtime::{AgentRuntime, ResourceBudget};
        use rusqlite::Connection;
        use std::cell::RefCell;
        use std::rc::Rc;

        let conn = Connection::open_in_memory().unwrap();
        let shared = std::sync::Arc::new(std::sync::Mutex::new(conn));
        let cp_store = CheckpointStore::new(std::sync::Arc::clone(&shared)).unwrap();

        let mut rt = AgentRuntime::new(
            "emo_recovery".to_string(),
            None,
            None,
            ResourceBudget::new(None, None, None),
        );
        rt.emotional_state.confidence = 0.3;
        rt.emotional_state.urgency = 0.8;
        rt.emotional_state.uncertainty = 0.9;
        cp_store
            .save_checkpoint("emo_recovery", &rt, "[]", 50)
            .unwrap();

        let loaded = cp_store
            .load_latest_checkpoint("emo_recovery")
            .unwrap()
            .unwrap();
        assert!((loaded.confidence - 0.3).abs() < f64::EPSILON);
        assert!((loaded.urgency - 0.8).abs() < f64::EPSILON);
        assert!((loaded.uncertainty - 0.9).abs() < f64::EPSILON);
    }

