    #[test]
    fn set_shutdown_flag_stores_flag() {
        let mut interp = Interpreter::new();
        let flag = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        interp.set_shutdown_flag(std::sync::Arc::clone(&flag));
        assert!(interp.shutdown_flag.is_some());
        // Verify the flag is the same Arc
        flag.store(true, std::sync::atomic::Ordering::SeqCst);
        assert!(
            interp
                .shutdown_flag
                .as_ref()
                .unwrap()
                .load(std::sync::atomic::Ordering::SeqCst)
        );
    }

