    #[test]
    fn idempotency_store_fetch_cached_result() {
        // Simulate: agent fetches URL, result cached, second fetch returns cache
        use crate::agent_observability::{IdempotencyStore, generate_idempotency_key};
        use rusqlite::Connection;
        use std::cell::RefCell;
        use std::rc::Rc;

        let conn = Connection::open_in_memory().unwrap();
        let shared = std::sync::Arc::new(std::sync::Mutex::new(conn));
        let store = IdempotencyStore::new(std::sync::Arc::clone(&shared)).unwrap();

        let key = generate_idempotency_key("test_agent", "https://example.com/api", "GET");

        // First check: no cache
        assert!(store.check(&key).unwrap().is_none());

        // Simulate fetch success: record result
        store
            .record(&key, r#"{"price": 42}"#, 200, Some(24))
            .unwrap();

        // Second check: cache hit
        let cached = store.check(&key).unwrap();
        assert!(cached.is_some());
        let (body, status) = cached.unwrap();
        assert_eq!(body, r#"{"price": 42}"#);
        assert_eq!(status, Some(200));
    }

    #[test]
    fn shutdown_flag_triggers_agent_stop() {
        // Set shutdown flag before running agent => agent stops with "shutdown" error
        let source = r#"
            @agent_task(id: shutdown_test, timeout: 60.seconds, max_requests: 10)
            @legal(basis: .public_data, purpose: "test")
            async fn shutdown_agent() -> String {
                let x = 1
                let y = 2
                "done"
            }
            fn main() {
                let r = shutdown_agent().await
                print(r)
            }
        "#;
        let (tokens, lex_errors) = lexer::tokenize(source);
        assert!(lex_errors.is_empty());
        let program = Parser::parse(tokens).unwrap();

        let mut interp = Interpreter::new();
        let flag = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(true));
        interp.set_shutdown_flag(flag);

        let result = interp.run(&program);
        assert!(result.is_err());
        let err_msg = result.unwrap_err().to_string();
        assert!(
            err_msg.contains("agent shutdown: state persisted"),
            "expected shutdown message, got: {}",
            err_msg
        );
    }

    #[test]
    fn shutdown_persists_checkpoint() {
        // Shutdown with Brain available => checkpoint saved to SQLite
        // Brain is created in main() and passed as argument to agent
        let source = r#"
            @agent_task(id: cp_shutdown, timeout: 60.seconds, max_requests: 10)
            @legal(basis: .public_data, purpose: "test")
            async fn cp_agent(brain: String) -> String {
                let x = 1
                let y = 2
                let z = 3
                "done"
            }
            fn main() {
                let brain = Brain { working_capacity: 10, persistence: ":memory:" }
                brain.working.store("state", "running")
                let r = cp_agent("test").await
                print(r)
            }
        "#;
        let (tokens, lex_errors) = lexer::tokenize(source);
        assert!(lex_errors.is_empty());
        let program = Parser::parse(tokens).unwrap();

        let mut interp = Interpreter::new();
        let flag = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(true));
        interp.set_shutdown_flag(flag);

        let result = interp.run(&program);
        assert!(result.is_err());
        let err_msg = result.unwrap_err().to_string();
        assert!(
            err_msg.contains("agent shutdown: state persisted"),
            "got: {}",
            err_msg
        );
    }

    #[test]
    fn full_lifecycle_checkpoint_recovery() {
        // Test: create checkpoint store, save checkpoint, then run agent that would recover from it
        use crate::agent_observability::CheckpointStore;
        use crate::agent_runtime::{AgentRuntime, ResourceBudget};
        use rusqlite::Connection;
        use std::cell::RefCell;
        use std::rc::Rc;

        // Phase 1: Create checkpoint at step 10
        let conn = Connection::open_in_memory().unwrap();
        let shared = std::sync::Arc::new(std::sync::Mutex::new(conn));
        let cp_store = CheckpointStore::new(std::sync::Arc::clone(&shared)).unwrap();

        let mut rt = AgentRuntime::new(
            "lifecycle_agent".to_string(),
            None,
            None,
            ResourceBudget::new(Some(100), None, Some(std::time::Duration::from_secs(60))),
        );
        rt.steps_executed = 10;
        rt.emotional_state.confidence = 0.7;
        rt.goals_attempted = 5;
        rt.goals_completed = 3;
        cp_store
            .save_checkpoint(
                "lifecycle_agent",
                &rt,
                r#"[{"key":"phase","value":"running"}]"#,
                20,
            )
            .unwrap();

        // Phase 2: Verify recovery
        let loaded = cp_store
            .load_latest_checkpoint("lifecycle_agent")
            .unwrap()
            .unwrap();
        assert_eq!(loaded.steps_executed, 10);
        assert!((loaded.confidence - 0.7).abs() < f64::EPSILON);
        assert_eq!(loaded.goals_attempted, 5);
        assert_eq!(loaded.goals_completed, 3);
        assert!(loaded.working_memory.contains("running"));
    }

    #[test]
    fn agent_health_after_recovery() {
        // Verify agent_health() returns correct values after checkpoint recovery
        use crate::agent_observability::CheckpointStore;
        use crate::agent_runtime::{AgentRuntime, ResourceBudget};
        use rusqlite::Connection;
        use std::cell::RefCell;
        use std::rc::Rc;

        let conn = Connection::open_in_memory().unwrap();
        let shared = std::sync::Arc::new(std::sync::Mutex::new(conn));
        let cp_store = CheckpointStore::new(std::sync::Arc::clone(&shared)).unwrap();

        let mut rt = AgentRuntime::new(
            "health_recovery".to_string(),
            None,
            None,
            ResourceBudget::new(Some(50), None, Some(std::time::Duration::from_secs(120))),
        );
        rt.steps_executed = 25;
        rt.budget.requests_used = 12;
        rt.emotional_state.confidence = 0.85;
        rt.emotional_state.urgency = 0.4;
        rt.goals_attempted = 8;
        rt.goals_completed = 6;
        cp_store
            .save_checkpoint("health_recovery", &rt, "[]", 50)
            .unwrap();

        let loaded = cp_store
            .load_latest_checkpoint("health_recovery")
            .unwrap()
            .unwrap();
        assert_eq!(loaded.steps_executed, 25);
        assert_eq!(loaded.requests_used, 12);
        assert!((loaded.confidence - 0.85).abs() < f64::EPSILON);
        assert!((loaded.urgency - 0.4).abs() < f64::EPSILON);
        assert_eq!(loaded.goals_attempted, 8);
        assert_eq!(loaded.goals_completed, 6);
    }

    #[test]
    fn spawn_agent_inherits_trace_id() {
        // Verify child agent inherits parent's trace_id
        let (_, output) = run(r#"
            @agent_task(id: trace_parent, timeout: 60.seconds, max_requests: 10, can_spawn: true)
            @legal(basis: .public_data, purpose: "test")
            async fn trace_parent() -> String {
                let result = spawn_agent("trace_child", "hello")
                result match {
                    Ok(v) -> v
                    Err(e) -> "error: " + e
                }
            }

            @agent_task(id: trace_child, timeout: 30.seconds, max_requests: 5)
            @legal(basis: .public_data, purpose: "test")
            async fn trace_child(msg: String) -> String {
                "child got: " + msg
            }

            fn main() {
                let r = trace_parent().await
                print(r)
            }
        "#);
        assert_eq!(output, vec!["child got: hello"]);
    }

