    #[test]
    fn test_provenance_method_dispatch() {
        // Test .provenance() method via call_method
        let inner = Value::String("data".to_string());
        let chain = ProvenanceChain::new(ProvenanceOrigin::FileRead {
            path: "/tmp/test.txt".to_string(),
            timestamp: "200s".to_string(),
        });
        let wrapped = Value::Provenance(Box::new(inner), Box::new(chain));

        let mut interp = Interpreter::new();
        let result = interp.call_method(wrapped, "provenance", vec![]);
        assert!(result.is_ok(), "provenance method should succeed");
        let prov = result.unwrap();
        if let Value::Struct { name, fields } = &prov {
            assert_eq!(name, "Provenance");
            let origin = fields.iter().find(|(k, _)| k == "origin").map(|(_, v)| v);
            assert!(origin.is_some());
            let origin_str = origin.unwrap().as_string();
            assert!(
                origin_str.contains("FileRead"),
                "origin should contain FileRead: {origin_str}"
            );
        } else {
            panic!("expected Struct, got: {}", prov.as_string());
        }
    }

    #[test]
    fn test_provenance_method_on_non_provenance() {
        let val = Value::Int(42);
        let mut interp = Interpreter::new();
        let result = interp.call_method(val, "provenance", vec![]);
        assert!(result.is_ok());
        let prov = result.unwrap();
        if let Value::Struct { fields, .. } = &prov {
            let origin = fields.iter().find(|(k, _)| k == "origin").map(|(_, v)| v);
            assert_eq!(origin.unwrap().as_string(), "Unknown");
        } else {
            panic!("expected Struct");
        }
    }

