    #[test]
    fn test_anonymize_k3() {
        let src = r#"
struct Person { name: String, age: i32, city: String }
fn main() {
    let people = [
        Person { name: "Alice", age: 25, city: "NYC" },
        Person { name: "Bob", age: 26, city: "NYC" },
        Person { name: "Carol", age: 25, city: "LA" },
        Person { name: "Dave", age: 30, city: "NYC" },
        Person { name: "Eve", age: 31, city: "LA" },
        Person { name: "Frank", age: 25, city: "NYC" },
        Person { name: "Grace", age: 26, city: "NYC" },
        Person { name: "Heidi", age: 30, city: "LA" },
        Person { name: "Ivan", age: 25, city: "NYC" },
        Person { name: "Judy", age: 31, city: "LA" }
    ]
    let anon = people.anonymize(k: 3)
    print("count: {anon.len()}")
}
"#;
        let (_, output) = run(src);
        // All records should survive in groups >= 3
        let count_line = &output[0];
        let count: usize = count_line.strip_prefix("count: ").unwrap().parse().unwrap();
        assert!(
            count >= 3,
            "anonymized result should have >= 3 records, got {count}"
        );
        // Every group must have >= 3 members (verified by algo)
    }

