    #[test]
    fn test_anonymize_non_array_error() {
        let mut interp = Interpreter::new();
        let result = interp.call_method(Value::Int(42), "anonymize", vec![Value::Int(3)]);
        assert!(result.is_err());
        assert!(format!("{:?}", result.unwrap_err()).contains("requires an array of structs"));
    }

