    #[test]
    fn zk_verify_tampered_proof() {
        // Verify that different inputs produce different proofs
        let src = r#"
@zk(scheme: .groth16)
fn add(a: i32, b: i32) -> i32 {
    a + b
}

fn main() {
    let proof1 = ZkCircuit.prove("add", [3, 7])
    let proof2 = ZkCircuit.prove("add", [100, 200])
    let v1 = ZkCircuit.verify(proof1)
    let v2 = ZkCircuit.verify(proof2)
    print(v1)
    print(v2)
    let same = proof1.proof_bytes == proof2.proof_bytes
    print(same)
}
"#;
        let (_, output) = run(src);
        assert_eq!(output[0], "true", "proof1 should verify");
        assert_eq!(output[1], "true", "proof2 should verify");
        assert_eq!(
            output[2], "false",
            "different inputs should produce different proofs"
        );
    }

