    // ── MPC (Multi-Party Computation) tests ─────────────────────────────

    #[test]
    fn test_mpc_session_create_contribute_compute() {
        let src = r#"
fn sum(a: i32, b: i32, c: i32) -> i32 {
    a + b + c
}

fn main() {
    let session = MpcSession.create(parties: 3)
    print(session.status)
    let s1 = session.contribute(10)
    let s2 = s1.contribute(20)
    let s3 = s2.contribute(30)
    let result = s3.compute("sum")
    print(result)
}
"#;
        let (_, output) = run(src);
        // compute() runs the named function over the contributed shares and returns its value.
        // It used to return an `Encrypted` wrapper whose `decrypt()` — the FHE unwrap, which
        // validates an `FheKey` and hands back `.inner` — could not open it, and whose
        // AES-256-GCM key was the process constant BLAKE3("mpc-computation-key"), so it
        // concealed nothing either. Stub #92's design call was taken in favour of dropping the
        // decoration, which is why this asserts the computed value and not the shape of a
        // wrapper nobody could open.
        assert_eq!(output[0], "collecting");
        assert_eq!(output[1], "60");
    }

