    #[test]
    fn test_contract_violation_detected() {
        let src = r#"
@requires(x > 0)
fn positive_only(x: i32) -> i32 {
    x * 2
}
fn main() {
    let a = positive_only(-1)
    print(a)
}
"#;
        let (tokens, lex_errors) = lexer::tokenize(src);
        assert!(lex_errors.is_empty());
        let program = Parser::parse(tokens).unwrap();
        let mut interp = Interpreter::new();
        interp.contracts_enabled = true;
        let result = interp.run(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err().to_string();
        assert!(
            msg.contains("contract violation"),
            "expected contract violation, got: {msg}"
        );
        assert!(
            msg.contains("positive_only"),
            "expected function name in error, got: {msg}"
        );
    }

    #[test]
    fn test_contract_disabled_no_violation() {
        let src = r#"
@requires(x > 0)
fn positive_only(x: i32) -> i32 {
    x * 2
}
fn main() {
    let a = positive_only(-1)
    print(a)
}
"#;
        let (tokens, lex_errors) = lexer::tokenize(src);
        assert!(lex_errors.is_empty());
        let program = Parser::parse(tokens).unwrap();
        let mut interp = Interpreter::new();
        interp.contracts_enabled = false;
        let result = interp.run(&program);
        assert!(
            result.is_ok(),
            "expected success with contracts disabled, got: {:?}",
            result
        );
        assert_eq!(interp.output[0], "-2");
    }

