    #[test]
    fn test_yara_rule_compile_scan() {
        // Avoid $ and { in Tallow strings — use pa/pb pattern names and no braces
        let src = concat!(
            "fn main() \\{\n",
            "    let rule = YaraRule.compile(\"rule test_rule\\n  strings:\\n    pa = \\\"malware\\\"\\n    pb = \\\"payload\\\"\\n  condition:\\n    any of them\")\n",
            "    print(rule.rule_name)\n",
            "    print(rule.patterns_count)\n",
            "    print(rule.compiled)\n",
            "    let result = YaraRule.scan(rule, \"this contains malware and payload strings\")\n",
            "    let count = YaraRule.match_count(result)\n",
            "    print(count)\n",
            "\\}\n",
        );
        // Build Tallow source properly: the concat is the Tallow source with escaped chars
        // We need literal Tallow source, so build it in Rust
        let src = "fn main() {\n    let rule = YaraRule.compile(\"rule test_rule\\n  strings:\\n    pa = \\\"malware\\\"\\n    pb = \\\"payload\\\"\\n  condition:\\n    any of them\")\n    print(rule.rule_name)\n    print(rule.patterns_count)\n    print(rule.compiled)\n    let result = YaraRule.scan(rule, \"this contains malware and payload strings\")\n    let count = YaraRule.match_count(result)\n    print(count)\n}\n";
        let (_, output) = run(src);
        assert_eq!(output[0], "test_rule");
        assert_eq!(output[1], "2");
        assert_eq!(output[2], "true");
        assert_eq!(output[3], "2"); // both patterns found
    }

