    #[test]
    fn test_anomaly_detector_zscore() {
        let src = r#"
fn main() {
    let det = AnomalyDetector.create("zscore")
    // Add normal datapoints around 10.0
    let det = AnomalyDetector.add_datapoint(det, 10.0)
    let det = AnomalyDetector.add_datapoint(det, 10.5)
    let det = AnomalyDetector.add_datapoint(det, 9.5)
    let det = AnomalyDetector.add_datapoint(det, 10.2)
    let det = AnomalyDetector.add_datapoint(det, 9.8)
    let det = AnomalyDetector.add_datapoint(det, 10.1)
    let det = AnomalyDetector.add_datapoint(det, 9.9)
    let det = AnomalyDetector.add_datapoint(det, 10.3)

    // Normal value — should NOT be anomaly
    let normal = AnomalyDetector.detect(det, 10.0)
    print(normal)

    // Extreme value — should be anomaly
    let anomaly = AnomalyDetector.detect(det, 50.0)
    print(anomaly)

    let thresh = AnomalyDetector.threshold(det)
    // threshold should be mean + 2*stddev, around 10.5-11.0
    let above_ten = thresh > 10.0
    print(above_ten)
}
"#;
        let (_, output) = run(src);
        assert_eq!(output[0], "false"); // 10.0 is normal
        assert_eq!(output[1], "true"); // 50.0 is anomalous
        assert_eq!(output[2], "true"); // threshold > 10
    }

