    #[ignore = "requires a reachable OTLP collector — export() POSTs to OTEL_EXPORTER_OTLP_ENDPOINT (the prometheus format is built in-process and does run)"]
    #[test]
    fn test_otel_exporter_otlp() {
        let src = r#"
fn main() {
    let exporter = OtelExporter.create("otlp")
    print(exporter.format)
    let metric = Metric.counter("requests", 100)
    let exported = OtelExporter.export(exporter, metric)
    let has_resource = exported.contains("resourceSpans")
    print(has_resource)
    let has_metric = exported.contains("requests")
    print(has_metric)
}
"#;
        // export() is fail-closed without OTEL_EXPORTER_OTLP_ENDPOINT, and .tl errors are fatal
        // (not catchable), so the exporter's documented precondition has to be satisfied here.
        // Spans are built in-process only - nothing is sent to this address.
        unsafe { std::env::set_var("OTEL_EXPORTER_OTLP_ENDPOINT", "http://localhost:4317") };
        let (_, output) = run(src);
        unsafe { std::env::remove_var("OTEL_EXPORTER_OTLP_ENDPOINT") };
        assert_eq!(output[0], "otlp");
        assert_eq!(output[1], "true");
        assert_eq!(output[2], "true");
    }

