    #[test]
    fn test_slo_evaluate_violation() {
        // SLI target 200ms, 1 of 4 measurements <= 200ms => 25% actual
        // SLO target 99.9% => in violation, high burn rate
        let src = r#"
fn main() {
    let sli = SLI.create("latency", 200.0, "ms")
    let sli = SLI.record(sli, 500.0)
    let sli = SLI.record(sli, 300.0)
    let sli = SLI.record(sli, 400.0)
    let sli = SLI.record(sli, 100.0)
    let slo = SLO.create("strict_slo", 99.9, 30)
    let result = SLO.evaluate(slo, sli)
    print(result.in_violation)
    let high_burn = result.burn_rate > 1.0
    print(high_burn)
}
"#;
        let (_, output) = run(src);
        assert_eq!(output[0], "true"); // 25% < 99.9% => violation
        assert_eq!(output[1], "true"); // burn rate > 1.0
    }

