    #[test]
    fn test_tpm_quote() {
        // Real Tpm.quote needs an openable TPM. Without one it must fail
        // honestly rather than fabricating a quote.
        let src = r#"
fn main() {
    let quote = Tpm.quote("test-nonce-42")
    print(quote.nonce)
}
"#;
        let err = match run_result(src) {
            Err(e) => e.to_string(),
            Ok(v) => panic!("Tpm.quote() must fail honestly without an openable TPM, got Ok({v:?})"),
        };
        let el = err.to_lowercase();
        assert!(
            ["tpm", "attestation", "tpmrm0", "tss"]
                .iter()
                .any(|kw| el.contains(kw)),
            "honest TPM error should mention the missing/unopenable TPM device, got: {err}"
        );
    }

