    #[test]
    fn test_hsm_list_slots() {
        // Real Hsm.list_slots enumerates PKCS#11 slots from the configured
        // provider. With a token present it returns a real slot count; without
        // a module/token it fails honestly — never a fabricated count.
        let src = r#"
fn main() {
    let slots = Hsm.list_slots()
    print(slots.len)
}
"#;
        match run_result(src) {
            Ok(_) => {
                let (_, output) = run(src);
                let n: usize = output[0].parse().expect("slots.len must be an integer");
                let _ = n; // real (possibly 0) count from the provider
            }
            Err(e) => {
                let el = e.to_string().to_lowercase();
                assert!(
                    ["pkcs11", "pkcs#11", "token", "slot", "module", "cryptoki", "softhsm"]
                        .iter()
                        .any(|kw| el.contains(kw)),
                    "honest HSM error should mention the missing PKCS#11 resource, got: {e}"
                );
            }
        }
    }

    #[test]
    fn test_enclave_attest_remote() {
        // Real Enclave.attest_remote needs a live SGX enclave/AESM; without one
        // it must fail honestly rather than fabricating a quote.
        let src = r#"
fn main() {
    let att = Enclave.attest_remote("my-enclave", "nonce-xyz")
    print(att.enclave_id)
}
"#;
        let err = match run_result(src) {
            Err(e) => e.to_string(),
            Ok(v) => panic!("Enclave.attest_remote() must fail honestly without a live enclave, got Ok({v:?})"),
        };
        let el = err.to_lowercase();
        assert!(
            ["enclave", "sgx", "attestation", "aesm"]
                .iter()
                .any(|kw| el.contains(kw)),
            "honest SGX error should mention the missing enclave/AESM resource, got: {err}"
        );
    }

