    #[test]
    fn test_secure_boot_measure_and_status() {
        let src = r#"
fn main() {
    let m = SecureBoot.measure("bootloader", "abc123")
    print(m.component)
    print(m.hash)
    let has_ext = m.extended_hash.len() > 0
    print(has_ext)
    let status = SecureBoot.status()
    print(status.secure_boot_enabled)
    print(status.chain_valid)
}
"#;
        // The `measure` half is deterministic and runs everywhere.
        let (_, output) = run(r#"
fn main() {
    let m = SecureBoot.measure("bootloader", "abc123")
    print(m.component)
    print(m.hash)
    let has_ext = m.extended_hash.len() > 0
    print(has_ext)
}
"#);
        assert_eq!(output[0], "bootloader");
        assert_eq!(output[1], "abc123");
        assert_eq!(output[2], "true");

        // The `status` half reads REAL UEFI efivar state, which is unavailable on
        // non-UEFI hosts (/sys/firmware/efi/efivars not readable). Accept either a
        // real status struct with boolean fields, or an honest no-efivars error —
        // never a fabricated/hardcoded state (mirrors the stdlib::crypto test).
        let full = run_result("fn main() {
            let status = SecureBoot.status()
            print(status.secure_boot_enabled)
            print(status.chain_valid)
            print(status.setup_mode)
        }");
        match full {
            Ok(_) => {
                let (_, out) = run("fn main() {
                    let status = SecureBoot.status()
                    print(status.secure_boot_enabled)
                    print(status.chain_valid)
                    print(status.setup_mode)
                }");
                assert!(
                    out[0] == "true" || out[0] == "false",
                    "secure_boot_enabled must be a boolean, got {}",
                    out[0]
                );
                assert!(
                    out[1] == "true" || out[1] == "false",
                    "chain_valid must be a boolean, got {}",
                    out[1]
                );
                assert!(
                    out[2] == "true" || out[2] == "false",
                    "setup_mode must be a boolean, got {}",
                    out[2]
                );
            }
            Err(e) => {
                let el = e.to_string().to_lowercase();
                assert!(
                    ["efivars", "uefi", "secureboot", "secure boot"]
                        .iter()
                        .any(|kw| el.contains(kw)),
                    "honest SecureBoot.status error should mention missing UEFI efivars, got: {e}"
                );
            }
        }
    }

