    #[test]
    fn test_qkd_session_keys_are_fresh() {
        // The BB84 emulation draws its key from the CSPRNG ("not quantum-random but
        // cryptographically secure" — see the implementation). Two sessions between the same
        // parties must NOT agree on the key: a deterministic key would be a vulnerability, and
        // the previous assertion demanded exactly that.
        let src = r#"
fn main() {
    let s1 = QuantumKeyDistribution.session("alice", "bob")
    let s2 = QuantumKeyDistribution.session("alice", "bob")
    print(s1.shared_key == s2.shared_key)
    print(len(s1.shared_key) > 0)
}
"#;
        let (_, output) = run(src);
        assert_eq!(output[0], "false");
        assert_eq!(output[1], "true");
    }

    #[test]
    fn test_pqc_migration_audit() {
        let src = r#"
fn main() {
    let report = PqcMigration.audit("rsa aes sha256 ml_kem hybrid")
    print(report.project)
    print(report.total_algorithms)
    print(report.classical_count)
    print(report.pqc_count)
    print(report.hybrid_count)
    print(report.migration_progress)
    let has_recs = len(report.recommendations) > 0
    print(has_recs)
}
"#;
        let (_, output) = run(src);
        // audit() counts algorithm mentions in the text it is handed (its own comment: "Count
        // actual crypto algorithm mentions in the program_info text"): three classical names
        // (rsa, aes, sha256), one PQC name (ml_kem) and the word hybrid. total is 5; progress is
        // (pqc + hybrid) / total = 2/5 = 40%. Values read off the implementation, not guessed.
        assert_eq!(output[0], "rsa aes sha256 ml_kem hybrid");
        assert_eq!(output[1], "5"); // total_algorithms
        assert_eq!(output[2], "3"); // classical_count
        assert_eq!(output[3], "1"); // pqc_count
        assert_eq!(output[4], "1"); // hybrid_count
        assert_eq!(output[5], "40%"); // migration_progress
        assert_eq!(output[6], "true");
    }

