    #[test]
    fn test_mls_group_create_add_encrypt_decrypt() {
        // All MLS tests share the process-wide MLS_GROUPS static. Running them
        // in parallel lets one test's clear() race another's create(), so
        // serialize them behind a test-scoped mutex.
        let _mls_serial = MLS_TEST_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        MLS_GROUPS.lock().unwrap_or_else(|e| e.into_inner()).clear();
        let src = r#"
fn main() {
    let group = MlsGroup.create("team-alpha")
    print(group.group_id)
    print(group.epoch)
    let group = MlsGroup.add_member(group, "alice")
    print(group.epoch)
    let group = MlsGroup.add_member(group, "bob")
    print(group.epoch)
    print(len(group.members))
    let encrypted = MlsGroup.encrypt(group, "team message")
    let has_enc = encrypted.len() > 0
    print(has_enc)
    let decrypted = MlsGroup.decrypt(group, encrypted)
    let has_dec = decrypted.len() > 0
    print(has_dec)
}
"#;
        let (_, output) = run(src);
        assert_eq!(output[0], "team-alpha");
        assert_eq!(output[1], "0");
        assert_eq!(output[2], "1");
        assert_eq!(output[3], "2");
        assert_eq!(output[4], "2");
        assert_eq!(output[5], "true");
        assert_eq!(output[6], "true");
    }

