    fn test_mls_group_epoch() {
        let _mls_serial = MLS_TEST_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        MLS_GROUPS.lock().unwrap_or_else(|e| e.into_inner()).clear();
        let src = r#"
fn main() {
    let group = MlsGroup.create("epoch-test")
    let e0 = MlsGroup.epoch(group)
    print(e0)
    let group = MlsGroup.add_member(group, "charlie")
    let e1 = MlsGroup.epoch(group)
    print(e1)
    let group = MlsGroup.remove_member(group, "charlie")
    let e2 = MlsGroup.epoch(group)
    print(e2)
}
"#;
        let (_, output) = run(src);
        assert_eq!(output[0], "0");
        assert_eq!(output[1], "1");
        assert_eq!(output[2], "2");
    }

