    /// R2-5: the Phase-50 namespace arms (Dialog/Keyboard/Mouse/Page extras)
    /// cannot touch a live page in function dispatch — the ones that used to
    /// fake success must be honest errors now (see `dispatch_no_page_bound`).
    fn assert_no_page_bound_error(program: &str, call: &str) {
        let err =
            run_result(program).expect_err(&format!("{call} must error without a live page"));
        let msg = format!("{err}");
        assert!(msg.contains(call), "diagnostic must name the call: {msg}");
        assert!(
            msg.contains("no page bound"),
            "diagnostic must say why it cannot work: {msg}"
        );
    }

    #[test]
    fn test_dialog_on_alert_accept() {
        // R2-5: both arms used to fake success (`active: true`,
        // `accepted: true`) with no browser; they are honest errors now.
        assert_no_page_bound_error(
            r#"
fn main() {
    let h = Dialog.on_alert("my_handler")
}
"#,
            "Dialog.on_alert",
        );
        assert_no_page_bound_error(
            r#"
fn main() {
    let r = Dialog.accept("ok clicked")
}
"#,
            "Dialog.accept",
        );
    }

