    #[test]
    fn test_page_set_content_errors_without_a_live_page() {
        // S3 (audit-05 F-4, site 3): the namespace-form stub must not fake
        // success — no live page is bound in function dispatch, so the call
        // is an explicit error instead of loaded:true for work never done.
        let result = run_result(
            r#"
fn main() {
    let r = Page.set_content("<html><body>Hello</body></html>")
    print(r.loaded)
}
"#,
        );
        let err = result.expect_err("Page.set_content must error without a live page");
        let msg = format!("{err}");
        assert!(
            msg.contains("Page.set_content"),
            "diagnostic must name the call: {msg}"
        );
        assert!(
            msg.contains("no page bound"),
            "diagnostic must say why it cannot work: {msg}"
        );
        // The arg check still fires first when html is missing.
        let result = run_result(
            r#"
fn main() {
    let r = Page.set_content()
}
"#,
        );
        let err = result.expect_err("missing html must error");
        assert!(
            format!("{err}").contains("requires html argument"),
            "missing-arg diagnostic: {err}"
        );
    }

