    #[test]
    fn test_default_param_applied_for_dynamic_call() {
        // R2-3 (audit a01:77): the default used to be parsed and dropped —
        // calls through a function value silently bound `nil` for the
        // omitted argument. The AST carries the default now and the
        // interpreter applies it.
        let (_, output) = run(r#"
fn pick(a: String, b: String = "first") -> String {
    return b
}
fn main() {
    let f = pick
    print(f("x"))
}
"#);
        assert_eq!(output[0], "first");
    }

    #[test]
    fn test_default_param_applied_for_direct_call_in_interpreter() {
        // The full CLI pipeline typechecks first and rejects a missing
        // argument (E0103 "expects 2 argument(s), got 1" — verified with
        // `tallow check` / `tallow run` on a probe file). The interpreter
        // itself, when reached without the typecheck stage (this harness),
        // applies the declared default instead of binding a silent nil.
        let (_, output) = run(r#"
fn greet(name: String, greeting: String = "hello") -> String {
    return greeting + " " + name
}
fn main() {
    print(greet("world"))
}
"#);
        assert_eq!(output[0], "hello world");
    }

