    // ══════════════════════════════════════════════════════════════════════
    // Phase 54: Sentinel fallback tests (no live browser). R2-5: arms that
    // used to fake success (`active: true`, `accepted: true`, …) are honest
    // errors now; descriptive arms (no outcome claims) still return their
    // offline structures. The real CDP-backed implementations live in the
    // BrowserObject dispatch and are exercised when a live Page handle exists.
    // ══════════════════════════════════════════════════════════════════════

    #[test]
    fn test_phase54_sentinel_dialog_all_types() {
        // R2-5: on_confirm/on_prompt stay descriptive; on_alert/accept/dismiss
        // are honest errors now (no fake `active`/`accepted`/`dismissed`).
        let (_, output) = run(r#"
fn main() {
    let c = Dialog.on_confirm("my_confirm", true)
    print(c.kind)
    print(c.auto_accept)
    let p = Dialog.on_prompt("my_prompt", "default")
    print(p.kind)
    print(p.default_value)
}
"#);
        assert_eq!(output[0], "confirm");
        assert_eq!(output[1], "true");
        assert_eq!(output[2], "prompt");
        assert_eq!(output[3], "default");
        assert_no_page_bound_error(
            r#"
fn main() {
    let a = Dialog.on_alert("my_alert")
}
"#,
            "Dialog.on_alert",
        );
        assert_no_page_bound_error(
            r#"
fn main() {
    let acc = Dialog.accept("ok")
}
"#,
            "Dialog.accept",
        );
        assert_no_page_bound_error(
            r#"
fn main() {
    let dis = Dialog.dismiss()
}
"#,
            "Dialog.dismiss",
        );
    }

