    #[test]
    fn test_phase55_transfer_hash() {
        // Create a temp file, hash it via Transfer.hash, verify non-empty hex
        let dir = tempfile::TempDir::new().unwrap();
        let file_path = dir.path().join("test_hash.txt");
        std::fs::write(&file_path, "hello transfer hash").unwrap();
        let path_str = file_path.to_string_lossy().to_string().replace('\\', "/");
        let src = format!(
            r#"
fn main() {{
    let h = Transfer.hash("{path_str}")
    let long_enough = h.len() == 64
    print(long_enough)
    print(h)
}}
"#
        );
        let (_, output) = run(&src);
        assert_eq!(output[0], "true");
        // Verify it's a valid 64-char hex string
        assert_eq!(output[1].len(), 64);
        assert!(output[1].chars().all(|c| c.is_ascii_hexdigit()));
    }

