    #[test]
    fn test_phase57_manifest_url_roundtrip() {
        let (_, output) = run(r#"
fn main() {
    let json = "hello-manifest"
    let url = Manifest.to_url(json)
    print(url)
    let decoded = Manifest.from_url(url)
    print(decoded)
    let qr = Manifest.to_qr(json)
    print(qr)
}
"#);
        assert!(
            output[0].starts_with("tallow://transfer/"),
            "URL prefix: {}",
            output[0]
        );
        assert_eq!(output[1], "hello-manifest");
        // Manifest.to_qr builds a self-contained HTML page that renders the transfer URL as a QR
        // code and returns it as a data: URI (stdlib/transfer.rs, manifest_to_qr). The previous
        // assertion expected a `QR[tallow://transfer/` label the implementation has never produced.
        assert!(
            output[2].starts_with("data:text/html;base64,"),
            "to_qr returns the rendered page as a data: URI, got: {}",
            output[2]
        );
        assert!(
            output[2].len() > 500,
            "the QR page should carry the whole template, got {} bytes",
            output[2].len()
        );
    }

