    #[test]
    fn test_browser_audit_full_pipeline() {
        // All BrowserAudit tests combined in one to avoid global state races.
        // The BROWSER_AUDIT_LOG is a global LazyLock, so parallel tests would
        // interfere with each other's entry counts.
        BROWSER_AUDIT_LOG
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .clear();
        let (_, output) = run(r#"
fn main() {
    // Test 1: log + chain verification
    let e1 = BrowserAudit.log("navigate", "https://example.com", "public_data", "initial visit")
    print(e1.action)
    print(e1.url)
    print(e1.legal_basis)
    let e2 = BrowserAudit.log("scrape", "https://example.com/products", "public_data", "price extraction")
    let e3 = BrowserAudit.log("store", "https://example.com/data", "consent", "saving results")
    // Chain: e2.prev_hash == e1.entry_hash, e3.prev_hash == e2.entry_hash
    let chain_ok = e2.prev_hash == e1.entry_hash
    print(chain_ok)
    let chain_ok2 = e3.prev_hash == e2.entry_hash
    print(chain_ok2)

    // Test 2: verify chain integrity
    let v = BrowserAudit.verify()
    print(v.chain_intact)
    print(v.entries)

    // Test 3: export JSON
    let exp = BrowserAudit.export("json")
    print(exp.format)
    print(exp.count)

    // Test 4: export text
    let exp_t = BrowserAudit.export("text")
    print(exp_t.format)
    print(exp_t.count)

    // Test 5: compliance report EU
    let r = BrowserAudit.compliance_report("eu")
    print(r.jurisdiction)
    print(r.status)

    // Test 6: compliance report US
    let r_us = BrowserAudit.compliance_report("us")
    print(r_us.status)
}
"#);
        assert_eq!(output[0], "navigate");
        assert_eq!(output[1], "https://example.com");
        assert_eq!(output[2], "public_data");
        assert_eq!(output[3], "true"); // chain e1->e2
        assert_eq!(output[4], "true"); // chain e2->e3
        assert_eq!(output[5], "true"); // chain_intact
        assert_eq!(output[6], "3"); // 3 entries
        assert_eq!(output[7], "json");
        assert_eq!(output[8], "3"); // 3 entries in JSON export
        assert_eq!(output[9], "text");
        assert_eq!(output[10], "3"); // 3 entries in text export
        assert_eq!(output[11], "eu");
        assert_eq!(output[12], "compliant");
        assert_eq!(output[13], "compliant"); // US compliance
    }

